public struct SessionCandidate: Codable, Equatable {
    public let role: String
    public let localIP: String
    public let localPort: UInt16
    public let publicIP: String
    public let publicPort: UInt16

    public init(role: String, localIP: String, localPort: UInt16, publicIP: String, publicPort: UInt16) {
        self.role = role; self.localIP = localIP; self.localPort = localPort
        self.publicIP = publicIP; self.publicPort = publicPort
    }
}

public class SignalingClient {
    private let pin: String
    private let role: String
    private var webSocketTask: URLSessionWebSocketTask?
    private var isSearching = false
    private var pendingContinuation: CheckedContinuation<SessionCandidate, Error>?
    private var activeTask: URLSessionDataTask?
    private let lock = NSLock()

    public init(pin: String, role: String) {
        self.pin = pin
        self.role = role
    }

    deinit { stop() }

    public func exchangeCandidate(_ local: SessionCandidate) async throws -> SessionCandidate {
        // Post our candidate to ntfy.sh/<pin>
        let topicURL = URL(string: "https://ntfy.sh/eclipticrd-\(pin)")!

        let encoder = JSONEncoder()
        let payload = try encoder.encode(local)

        var postRequest = URLRequest(url: topicURL)
        postRequest.httpMethod = "POST"
        postRequest.httpBody = payload
        postRequest.setValue("application/json", forHTTPHeaderField: "Content-Type")

        ERDLog.network("[Signaling] Posting candidate to ntfy.sh/eclipticrd-\(pin)")
        let _ = try await URLSession.shared.data(for: postRequest)

        // Subscribe via SSE (Server-Sent Events) and wait for peer's candidate
        return try await withCheckedThrowingContinuation { continuation in
            lock.lock()
            isSearching = true
            pendingContinuation = continuation
            lock.unlock()

            var sseURL = URLComponents(url: topicURL.appendingPathComponent("json"), resolvingAgainstBaseURL: false)!
            sseURL.queryItems = [URLQueryItem(name: "poll", value: "1"), URLQueryItem(name: "since", value: "5m")]

            var request = URLRequest(url: sseURL.url!)
            request.timeoutInterval = 30

            let task = URLSession.shared.dataTask(with: request) { [weak self] data, _, error in
                guard let self = self else { return }

                self.lock.lock()
                guard self.isSearching else {
                    // Already cancelled via stop() — continuation was already resumed there
                    self.lock.unlock()
                    return
                }
                self.isSearching = false
                self.pendingContinuation = nil
                self.lock.unlock()

                if let error = error {
                    continuation.resume(throwing: error)
                    return
                }
                guard let data = data else {
                    continuation.resume(throwing: NSError(domain: "Signaling", code: 1, userInfo: [NSLocalizedDescriptionKey: "Signaling timeout waiting for peer"]))
                    return
                }

                // Parse JSON lines from ntfy.sh response
                let lines = String(data: data, encoding: .utf8)?.split(separator: "\n") ?? []
                let decoder = JSONDecoder()

                for line in lines.reversed() {
                    // Each line is a ntfy message JSON containing a "message" field
                    if let lineData = line.data(using: .utf8),
                       let ntfyMessage = try? JSONSerialization.jsonObject(with: lineData) as? [String: Any],
                       let messageStr = ntfyMessage["message"] as? String,
                       let messageData = messageStr.data(using: .utf8),
                       let candidate = try? decoder.decode(SessionCandidate.self, from: messageData),
                       candidate.role != self.role {
                        continuation.resume(returning: candidate)
                        return
                    }
                }

                continuation.resume(throwing: NSError(domain: "Signaling", code: 2, userInfo: [NSLocalizedDescriptionKey: "Signaling timeout waiting for peer"]))
            }
            activeTask = task
            task.resume()
        }
    }

    public func stop() {
        lock.lock()
        isSearching = false
        activeTask?.cancel()
        activeTask = nil
        let continuation = pendingContinuation
        pendingContinuation = nil
        lock.unlock()

        // Resume outside lock to avoid potential deadlock
        continuation?.resume(throwing: CancellationError())

        webSocketTask?.cancel(with: .goingAway, reason: nil)
        webSocketTask = nil
    }
}

import Foundation
import Network

public class STUNClient {
    private let serverHost: String
    private let serverPort: UInt16

    public init(serverHost: String = "stun.l.google.com", serverPort: UInt16 = 19302) {
        self.serverHost = serverHost
        self.serverPort = serverPort
    }

    public func fetchPublicIP() async throws -> (String, UInt16) {
        return try await withCheckedThrowingContinuation { continuation in
            let queue = DispatchQueue(label: "eclipticrd.stun")
            let endpoint = NWEndpoint.hostPort(host: NWEndpoint.Host(serverHost), port: NWEndpoint.Port(rawValue: serverPort)!)
            let params = NWParameters.udp
            if let ip = params.defaultProtocolStack.internetProtocol as? NWProtocolIP.Options {
                ip.version = .v4
            }
            let conn = NWConnection(to: endpoint, using: params)
            var completed = false

            func finish(result: Result<(String, UInt16), Error>) {
                guard !completed else { return }
                completed = true
                conn.cancel()
                switch result {
                case .success(let v): continuation.resume(returning: v)
                case .failure(let e): continuation.resume(throwing: e)
                }
            }

            conn.stateUpdateHandler = { [self] state in
                switch state {
                case .ready:
                    var request = Data(count: 20)
                    request[0] = 0x00; request[1] = 0x01
                    request[4] = 0x21; request[5] = 0x12; request[6] = 0xA4; request[7] = 0x42
                    for i in 8..<20 { request[i] = UInt8.random(in: 0...255) }

                    conn.send(content: request, completion: .contentProcessed { _ in })

                    conn.receiveMessage { data, _, _, error in
                        if let error = error {
                            finish(result: .failure(error))
                            return
                        }
                        guard let data = data, data.count >= 20 else {
                            finish(result: .failure(NSError(domain: "STUN", code: 1, userInfo: [NSLocalizedDescriptionKey: "Empty STUN response"])))
                            return
                        }
                        if let (ip, port) = Self.parseMappedAddress(from: data) {
                            finish(result: .success((ip, port)))
                        } else {
                            finish(result: .failure(NSError(domain: "STUN", code: 2, userInfo: [NSLocalizedDescriptionKey: "MAPPED-ADDRESS not found in STUN response"])))
                        }
                    }
                case .failed(let error):
                    finish(result: .failure(error))
                default:
                    break
                }
            }

            conn.start(queue: queue)

            queue.asyncAfter(deadline: .now() + 5.0) {
                finish(result: .failure(NSError(domain: "STUN", code: 3, userInfo: [NSLocalizedDescriptionKey: "STUN timeout"])))
            }
        }
    }

    private static func parseMappedAddress(from data: Data) -> (String, UInt16)? {
        let magicCookie: UInt32 = 0x2112A442
        var offset = 20 // Skip header

        while offset + 4 <= data.count {
            let attrType = UInt16(data[offset]) << 8 | UInt16(data[offset+1])
            let attrLen = Int(UInt16(data[offset+2]) << 8 | UInt16(data[offset+3]))
            offset += 4

            guard offset + attrLen <= data.count else { break }

            if attrType == 0x0020 { // XOR-MAPPED-ADDRESS
                guard attrLen >= 8 else { break }
                let family = data[offset + 1]
                let xPort = (UInt16(data[offset+2]) << 8 | UInt16(data[offset+3])) ^ UInt16(magicCookie >> 16)

                if family == 0x01 { // IPv4
                    let xAddr = UInt32(data[offset+4]) << 24 | UInt32(data[offset+5]) << 16 |
                                UInt32(data[offset+6]) << 8  | UInt32(data[offset+7])
                    let addr = xAddr ^ magicCookie
                    let ip = "\(addr >> 24 & 0xFF).\(addr >> 16 & 0xFF).\(addr >> 8 & 0xFF).\(addr & 0xFF)"
                    return (ip, xPort)
                }
            } else if attrType == 0x0001 { // MAPPED-ADDRESS (fallback)
                guard attrLen >= 8 else { break }
                let family = data[offset + 1]
                let port = UInt16(data[offset+2]) << 8 | UInt16(data[offset+3])

                if family == 0x01 {
                    let ip = "\(data[offset+4]).\(data[offset+5]).\(data[offset+6]).\(data[offset+7])"
                    return (ip, port)
                }
            }

            // Attributes are padded to 4-byte boundaries
            offset += (attrLen + 3) & ~3
        }
        return nil
    }
}

import Foundation
import Network

public class BonjourBrowser {
    public struct DiscoveredHost: Identifiable, Hashable, Equatable {
        public let id: String
        public let name: String
        public let endpoint: NWEndpoint

        public init(id: String, name: String, endpoint: NWEndpoint) {
            self.id = id; self.name = name; self.endpoint = endpoint
        }

        public var endpointDescription: String {
            switch endpoint {
            case .service(_, let type, let domain, _):
                return "\(type) (\(domain))"
            case .hostPort(let host, let port):
                return "\(host):\(port)"
            default:
                return "\(endpoint)"
            }
        }

        public func hash(into hasher: inout Hasher) { hasher.combine(id) }
        public static func == (lhs: DiscoveredHost, rhs: DiscoveredHost) -> Bool { lhs.id == rhs.id }
    }

    private var browser: NWBrowser?
    private let queue = DispatchQueue(label: "eclipticrd.bonjour")
    private var hosts: [DiscoveredHost] = []

    public var onHostsChanged: (@Sendable ([DiscoveredHost]) -> Void)?

    public init() {}

    public func startBrowsing() {
        let params = NWParameters()
        params.includePeerToPeer = true
        let descriptor = NWBrowser.Descriptor.bonjour(type: ERDConstants.bonjourServiceType, domain: ERDConstants.bonjourDomain)
        browser = NWBrowser(for: descriptor, using: params)

        browser?.browseResultsChangedHandler = { [weak self] results, _ in
            guard let self = self else { return }
            self.hosts = results.compactMap { result in
                if case .service(let name, _, _, _) = result.endpoint {
                    return DiscoveredHost(id: name, name: name, endpoint: result.endpoint)
                }
                return nil
            }
            ERDLog.network("[Bonjour] Found \(self.hosts.count) hosts")
            self.onHostsChanged?(self.hosts)
        }

        browser?.stateUpdateHandler = { state in
            if case .failed(let err) = state { ERDLog.error("[Bonjour] Browser failed: \(err)") }
        }

        browser?.start(queue: queue)
        ERDLog.network("[Bonjour] Browsing for services...")
    }

    public func stopBrowsing() {
        // Synchronize on queue to avoid data race with browseResultsChangedHandler
        queue.sync {
            browser?.cancel()
            browser = nil
            hosts = []
        }
    }
}

import Foundation
import AppKit

/// Monitors the system pasteboard for text changes and provides loop prevention
/// for bidirectional clipboard sync between host and client.
///
/// Loop prevention strategy:
/// - Tracks `changeCount` to detect local pasteboard changes
/// - When applying remote text, records the resulting changeCount to suppress the echo
/// - Uses content hash dedup to avoid sending identical text back
public class ClipboardMonitor {
    private let pasteboard = NSPasteboard.general
    private var pollTimer: DispatchSourceTimer?
    private let pollQueue = DispatchQueue(label: "eclipticrd.clipboard.poll")
    private let lock = NSLock()

    /// The changeCount after our last write, used to suppress echo
    private var lastWrittenChangeCount: Int = -1
    /// Hash of the last text we sent or applied, for content-level dedup
    private var lastTextHash: Int = 0
    /// Whether monitoring is active
    private var isRunning = false
    /// Last observed changeCount
    private var lastChangeCount: Int = 0

    private let onLocalChange: (String) -> Void

    /// - Parameter onLocalChange: Called when the local pasteboard text changes
    ///   (excluding changes applied via `applyRemoteText`).
    public init(onLocalChange: @escaping (String) -> Void) {
        self.onLocalChange = onLocalChange
    }

    public func start() {
        lock.lock()
        guard !isRunning else { lock.unlock(); return }
        isRunning = true
        lastChangeCount = pasteboard.changeCount
        lastWrittenChangeCount = -1
        lastTextHash = 0
        lock.unlock()

        let timer = DispatchSource.makeTimerSource(queue: pollQueue)
        timer.schedule(deadline: .now() + 0.5, repeating: 0.5)
        timer.setEventHandler { [weak self] in
            self?.poll()
        }
        timer.resume()
        pollTimer = timer
    }

    public func stop() {
        lock.lock()
        isRunning = false
        lock.unlock()
        pollTimer?.cancel()
        pollTimer = nil
    }

    /// Apply text received from the remote peer to the local pasteboard.
    /// The resulting changeCount is recorded so the next poll won't echo it back.
    public func applyRemoteText(_ text: String) {
        let hash = text.hashValue
        lock.lock()
        lastTextHash = hash
        lock.unlock()

        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)

        lock.lock()
        lastWrittenChangeCount = pasteboard.changeCount
        lastChangeCount = pasteboard.changeCount
        lock.unlock()
    }

    private func poll() {
        let currentCount = pasteboard.changeCount

        lock.lock()
        let running = isRunning
        let prevCount = lastChangeCount
        let writtenCount = lastWrittenChangeCount
        let prevHash = lastTextHash
        lock.unlock()

        guard running, currentCount != prevCount else { return }

        // Suppress echo: if this changeCount matches what we just wrote, skip
        if currentCount == writtenCount {
            lock.lock()
            lastChangeCount = currentCount
            lock.unlock()
            return
        }

        lock.lock()
        lastChangeCount = currentCount
        lock.unlock()

        guard let text = pasteboard.string(forType: .string), !text.isEmpty else { return }

        // Content-level dedup: don't send if identical to last sent/applied text
        let hash = text.hashValue
        guard hash != prevHash else { return }

        // Check size limit
        guard let textData = text.data(using: .utf8),
              textData.count <= ERDConstants.maxClipboardTextBytes else { return }

        lock.lock()
        lastTextHash = hash
        lock.unlock()

        onLocalChange(text)
    }
}

import Foundation
import Network
import CoreMedia
import CoreGraphics

public class ServerCore {
    public static let shared = ServerCore()

    private let tcpChannel = TCPChannel()
    private let udpChannel = UDPChannel()
    private var frameSender: FrameSender?
    private var inputReceiver: InputReceiver?
    private let screenCapture = ScreenCapture()
    private var videoEncoder: VideoEncoder?
    private var hostname: String = ""
    public private(set) var isRunning = false
    private var isStreaming = AtomicBool(false)
    // Protects inputReceiver, frameSender, videoEncoder from concurrent access
    // between tcpChannel.onReceive (TCP queue) and startStreaming/stopStreaming (async context).
    private let stateQueue = DispatchQueue(label: "eclipticrd.server.state")

    private var heartbeatTimer: DispatchSourceTimer?
    private let heartbeatQueue = DispatchQueue(label: "eclipticrd.server.heartbeat")
    private var lastPongTime: Date = Date()
    private let pongLock = NSLock()

    private var clipboardMonitor: ClipboardMonitor?
    private var peerCapabilities: HandshakeCapabilities = []
    private var activeStreamConfig: StreamConfiguration?

    public var onRunningChanged: (@Sendable (Bool) -> Void)?

    private init() {}

    public func start(pin: String? = nil) async {
        hostname = ProcessInfo.processInfo.hostName

        do {
            // 1. Start TCP listener for control/input
            try tcpChannel.startListening(port: ERDConstants.tcpPort)
            isRunning = true
            onRunningChanged?(true)

            // 2. Start UDP listener for video frames
            try udpChannel.startListening(port: ERDConstants.udpPort)
            ERDLog.info("[Server] Listening on UDP:\(ERDConstants.udpPort)")

            // 3. Set up handlers BEFORE advertising/signaling so incoming connections are handled
            tcpChannel.onConnect = { [weak self] in
                ERDLog.info("[Server] Client connected!")
                Task { await self?.startStreaming() }
            }
            tcpChannel.onDisconnect = { [weak self] in
                ERDLog.info("[Server] Client disconnected")
                Task { await self?.stopStreaming() }
            }
            tcpChannel.onReceive = { [weak self] data in
                guard let self = self else { return }
                guard data.count >= ERDConstants.packetHeaderSize else { return }
                guard let header = PacketHeader.deserialize(from: data) else {
                    return
                }
                let payload = data.subdata(in: ERDConstants.packetHeaderSize..<data.count)

                switch header.type {
                case .inputEvent:
                    let receiver = self.stateQueue.sync { self.inputReceiver }
                    receiver?.handleInputEvent(payload)
                case .control:
                    if let msg = ControlMessage.deserialize(from: payload) {
                        switch msg.type {
                        case .requestKeyFrame:
                            let encoder = self.stateQueue.sync { self.videoEncoder }
                            encoder?.forceKeyFrame()
                        case .startStream: Task { await self.startStreaming() }
                        case .stopStream: Task { await self.stopStreaming() }
                        case .disconnect: Task { await self.stop() }
                        case .ping: break
                        case .streamConfigRequest:
                            if let data = msg.payload,
                               let req = StreamConfigurationRequestPayload.deserialize(from: data) {
                                Task { await self.handleStreamConfigRequest(req) }
                            }
                        case .streamConfigResponse, .streamConfigReject, .streamConfigError:
                            break // Server doesn't process these
                        case .clipboardSyncRequest:
                            break // Clipboard start/stop handled at session level
                        case .clipboardSyncUpdate:
                            if let data = msg.payload,
                               let update = ClipboardSyncUpdatePayload.deserialize(from: data) {
                                self.handleClipboardUpdate(update)
                            }
                        case .clipboardSyncError:
                            if let data = msg.payload,
                               let err = ClipboardSyncErrorPayload.deserialize(from: data) {
                                ERDLog.warning("[Server] Clipboard sync error from client: \(err.message)")
                            }
                        case .pong:
                            self.pongLock.lock()
                            self.lastPongTime = Date()
                            self.pongLock.unlock()
                        case .bitrateAdjust:
                            if let data = msg.payload,
                               let adj = BitrateAdjustPayload.deserialize(from: data) {
                                let newBitrate = Int(adj.targetBitrate)
                                ERDLog.info("[Server] Bitrate adjust request: \(newBitrate)")
                                let encoder = self.stateQueue.sync { self.videoEncoder }
                                encoder?.updateBitrate(newBitrate)
                            }
                        }
                    }
                case .handshake:
                    if let hs = HandshakePayload.deserialize(from: payload) {
                        ERDLog.info("[Server] Received handshake from client: \(hs.hostname) caps=\(hs.capabilities.rawValue)")
                        self.stateQueue.sync { self.peerCapabilities = hs.capabilities }
                        if self.isStreaming.value {
                            self.startClipboardSync()
                        }
                    }
                default: break
                }
            }

            // 4. Advertise via Bonjour (handlers are ready for incoming connections)
            tcpChannel.advertiseService(name: hostname)
            ERDLog.info("[Server] Advertising as '\(hostname)' via Bonjour")

            // 5. If PIN provided, exchange candidates via signaling
            if let pin = pin {
                await startSignaling(pin: pin)
            }

            ERDLog.info("[Server] Waiting for client connection...")
        } catch {
            isRunning = false
            onRunningChanged?(false)
            ERDLog.error("[Server] Fatal error: \(error)")
        }
    }

    private func startSignaling(pin: String) async {
        do {
            let stun = STUNClient()
            let (publicIP, publicPort) = try await stun.fetchPublicIP()
            ERDLog.info("[Server] STUN Public IP: \(publicIP):\(publicPort)")

            let localIP = NetworkUtils.getLocalIP() ?? "127.0.0.1"
            let signaling = SignalingClient(pin: pin, role: "server")
            let ourCandidate = SessionCandidate(role: "server", localIP: localIP, localPort: ERDConstants.tcpPort,
                                                  publicIP: publicIP, publicPort: publicPort)

            ERDLog.info("[Server] Exchanging candidates via PIN: \(pin)")
            let _ = try await signaling.exchangeCandidate(ourCandidate)
            signaling.stop()
            ERDLog.info("[Server] Signaling complete, waiting for client TCP connection...")
        } catch {
            ERDLog.error("[Server] Signaling failed: \(error)")
        }
    }

    private func startStreaming() async {
        guard !isStreaming.value else {
            return
        }

        guard CGPreflightScreenCaptureAccess() else {
            ERDLog.warning("[Server] Screen Recording permission not granted")
            ERDLog.warning("[Server]    Go to System Settings > Privacy & Security > Screen Recording")
            return
        }

        isStreaming.value = true

        let info = screenCapture.getDisplayInfo()
        let initialConfiguration = StreamConfiguration(
            width: UInt32(info.pixelWidth),
            height: UInt32(info.pixelHeight),
            bitrate: UInt32(ERDConstants.defaultBitrate),
            framesPerSecond: UInt16(ERDConstants.defaultFPS)
        )

        stateQueue.sync {
            inputReceiver = InputReceiver(screenWidth: CGFloat(info.width), screenHeight: CGFloat(info.height))
            frameSender = FrameSender(udpChannel: udpChannel)
            activeStreamConfig = initialConfiguration
        }

        // Send handshake to client (logical resolution for coordinate mapping)
        let handshake = HandshakePayload(hostname: hostname, screenWidth: UInt16(info.width),
                                          screenHeight: UInt16(info.height), scaleFactor: Float(info.scale),
                                          capabilities: [.streamConfiguration, .textClipboardSync])
        let header = PacketHeader(type: .handshakeAck, sequence: 0, timestamp: 0)
        var packet = header.serialize()
        packet.append(handshake.serialize())
        tcpChannel.send(packet)

        let preferredFPS = UserDefaults.standard.integer(forKey: "preferredFPS")
        let fps = preferredFPS > 0 ? preferredFPS : ERDConstants.defaultFPS

        // Setup pipeline: capture → encode → send (physical resolution for encoding)
        let encoder = makeVideoEncoder(
            width: info.pixelWidth,
            height: info.pixelHeight,
            bitrate: ERDConstants.defaultBitrate,
            fps: fps
        )

        stateQueue.sync { videoEncoder = encoder }

        screenCapture.onFrame = { [weak self] sampleBuffer in
            guard let self = self else { return }
            let encoder = self.stateQueue.sync { self.videoEncoder }
            encoder?.encode(sampleBuffer)
        }
        screenCapture.onCursorPosition = { [weak self] point in
            guard let self = self else { return }
            let nx = Float(point.x) / Float(info.width)
            let ny = Float(point.y) / Float(info.height)
            let sender = self.stateQueue.sync { self.frameSender }
            sender?.sendCursorUpdate(x: nx, y: ny)
        }
        screenCapture.onAudio = { [weak self] sampleBuffer in
            self?.handleAudioFrame(sampleBuffer)
        }

        do {
            try encoder.start()
            try await screenCapture.start(fps: fps)
            startHeartbeat()
            startClipboardSync()
            ERDLog.info("[Server] Streaming started: \(info.width)x\(info.height)")
        } catch {
            isStreaming.value = false
            stopHeartbeat()
            do { try await screenCapture.stop() } catch { }
            stateQueue.sync {
                videoEncoder?.stop()
                videoEncoder = nil
                frameSender = nil
                inputReceiver = nil
                activeStreamConfig = nil
            }
            ERDLog.error("[Server] Failed to start streaming: \(error)")
        }
    }

    private func stopStreaming() async {
        guard isStreaming.value else { return }
        isStreaming.value = false
        stopClipboardSync()
        stopHeartbeat()
        do { try await screenCapture.stop() } catch { ERDLog.error("[Server] Error stopping capture: \(error)") }

        stateQueue.sync {
            videoEncoder?.stop()
            videoEncoder = nil
            frameSender = nil
            inputReceiver = nil
            activeStreamConfig = nil
        }
        ERDLog.info("[Server] Streaming stopped")
    }

    public func stop() async {
        await stopStreaming()
        tcpChannel.stop()
        udpChannel.stop()
        isRunning = false
        onRunningChanged?(false)
    }

    // MARK: - Stream Configuration

    private func handleStreamConfigRequest(_ request: StreamConfigurationRequestPayload) async {
        let desired = request.desiredConfiguration

        // Validate requested dimensions
        let info = screenCapture.getDisplayInfo()
        let maxW = UInt32(info.pixelWidth)
        let maxH = UInt32(info.pixelHeight)

        if desired.width > maxW || desired.height > maxH || desired.width == 0 || desired.height == 0 {
            let reject = StreamConfigurationRejectPayload(
                requestID: request.requestID,
                reason: .unsupportedDimensions,
                message: "Dimensions must be 1..\(maxW)x\(maxH)")
            let msg = ControlMessage(type: .streamConfigReject, payload: reject.serialize())
            tcpChannel.sendControl(msg)
            return
        }

        if desired.framesPerSecond == 0 || desired.framesPerSecond > 120 {
            let reject = StreamConfigurationRejectPayload(
                requestID: request.requestID,
                reason: .unsupportedFPS,
                message: "FPS must be 1..120")
            let msg = ControlMessage(type: .streamConfigReject, payload: reject.serialize())
            tcpChannel.sendControl(msg)
            return
        }

        let clampedBitrate = max(UInt32(ERDConstants.minBitrate), min(desired.bitrate, UInt32(ERDConstants.maxBitrate)))

        let currentConfiguration = stateQueue.sync { self.activeStreamConfig }
        let captureDimensionsChanged = currentConfiguration.map {
            Int($0.width) != Int(desired.width) || Int($0.height) != Int(desired.height)
        } ?? true

        if captureDimensionsChanged {
            let encoder = makeVideoEncoder(
                width: Int(desired.width),
                height: Int(desired.height),
                bitrate: Int(clampedBitrate),
                fps: Int(desired.framesPerSecond)
            )

            do {
                try encoder.start()
            } catch {
                encoder.stop()
                let errPayload = StreamConfigurationErrorPayload(
                    requestID: request.requestID,
                    errorCode: .invalidRequest,
                    message: "Failed to restart encoder: \(error.localizedDescription)")
                let msg = ControlMessage(type: .streamConfigError, payload: errPayload.serialize())
                tcpChannel.sendControl(msg)
                return
            }

            let oldEncoder = stateQueue.sync { () -> VideoEncoder? in
                let encoder = self.videoEncoder
                self.videoEncoder = nil
                return encoder
            }

            do {
                try await screenCapture.updateConfiguration(
                    width: Int(desired.width),
                    height: Int(desired.height),
                    fps: Int(desired.framesPerSecond)
                )
            } catch {
                encoder.stop()
                stateQueue.sync { self.videoEncoder = oldEncoder }
                let errPayload = StreamConfigurationErrorPayload(
                    requestID: request.requestID,
                    errorCode: .invalidRequest,
                    message: "Failed to update capture: \(error.localizedDescription)")
                let msg = ControlMessage(type: .streamConfigError, payload: errPayload.serialize())
                tcpChannel.sendControl(msg)
                return
            }

            stateQueue.sync { self.videoEncoder = encoder }
            oldEncoder?.stop()
        } else {
            do {
                try await screenCapture.updateConfiguration(
                    width: Int(desired.width),
                    height: Int(desired.height),
                    fps: Int(desired.framesPerSecond)
                )
            } catch {
                let errPayload = StreamConfigurationErrorPayload(
                    requestID: request.requestID,
                    errorCode: .invalidRequest,
                    message: "Failed to update capture: \(error.localizedDescription)")
                let msg = ControlMessage(type: .streamConfigError, payload: errPayload.serialize())
                tcpChannel.sendControl(msg)
                return
            }

            let encoder = stateQueue.sync { self.videoEncoder }
            encoder?.updateBitrate(Int(clampedBitrate))
            encoder?.updateFPS(Int(desired.framesPerSecond))
        }

        let applied = StreamConfiguration(
            width: desired.width,
            height: desired.height,
            bitrate: clampedBitrate,
            framesPerSecond: desired.framesPerSecond)
        stateQueue.sync { activeStreamConfig = applied }

        let response = StreamConfigurationResponsePayload(requestID: request.requestID, activeConfiguration: applied)
        let msg = ControlMessage(type: .streamConfigResponse, payload: response.serialize())
        tcpChannel.sendControl(msg)
        ERDLog.info("[Server] Stream config applied: \(applied.width)x\(applied.height) @\(applied.framesPerSecond)fps \(applied.bitrate)bps")
    }

    private func makeVideoEncoder(width: Int, height: Int, bitrate: Int, fps: Int) -> VideoEncoder {
        let encoder = VideoEncoder(width: width, height: height, bitrate: bitrate, fps: fps)
        encoder.onEncodedFrame = { [weak self] data, isKeyFrame in
            guard let self = self else { return }
            let sender = self.stateQueue.sync { self.frameSender }
            let activeConfiguration = self.stateQueue.sync { self.activeStreamConfig }
            let width = Int(activeConfiguration?.width ?? UInt32(width))
            let height = Int(activeConfiguration?.height ?? UInt32(height))
            sender?.sendFrame(data: data, width: width, height: height, isKeyFrame: isKeyFrame)
        }
        return encoder
    }

    // MARK: - Clipboard Sync

    private func startClipboardSync() {
        let existingMonitor = stateQueue.sync { self.clipboardMonitor }
        guard existingMonitor == nil else {
            return
        }

        let peerCaps = stateQueue.sync { self.peerCapabilities }
        guard peerCaps.contains(.textClipboardSync) else {
            ERDLog.info("[Server] Peer does not support clipboard sync, skipping")
            return
        }

        let monitor = ClipboardMonitor { [weak self] text in
            guard let self = self else { return }
            let update = ClipboardSyncUpdatePayload(
                requestID: 0,
                direction: .hostToClient,
                origin: .localPasteboard,
                text: text)
            if let data = update.serialize() {
                let msg = ControlMessage(type: .clipboardSyncUpdate, payload: data)
                self.tcpChannel.sendControl(msg)
            }
        }
        stateQueue.sync { self.clipboardMonitor = monitor }
        monitor.start()
        ERDLog.info("[Server] Clipboard sync started")
    }

    private func stopClipboardSync() {
        let monitor = stateQueue.sync { self.clipboardMonitor }
        monitor?.stop()
        stateQueue.sync { self.clipboardMonitor = nil }
    }

    private func handleClipboardUpdate(_ update: ClipboardSyncUpdatePayload) {
        let monitor = stateQueue.sync { self.clipboardMonitor }
        monitor?.applyRemoteText(update.text)
        ERDLog.info("[Server] Clipboard received from client (\(update.text.count) chars)")
    }

    // MARK: - Heartbeat

    private func startHeartbeat() {
        stopHeartbeat()
        pongLock.lock()
        lastPongTime = Date()
        pongLock.unlock()

        let timer = DispatchSource.makeTimerSource(queue: heartbeatQueue)
        timer.schedule(deadline: .now() + ERDConstants.heartbeatInterval,
                       repeating: ERDConstants.heartbeatInterval)
        timer.setEventHandler { [weak self] in
            guard let self = self, self.isStreaming.value else { return }

            self.tcpChannel.sendControl(ControlMessage(type: .ping))

            self.pongLock.lock()
            let elapsed = Date().timeIntervalSince(self.lastPongTime)
            self.pongLock.unlock()

            if elapsed > ERDConstants.heartbeatInterval * 3 {
                ERDLog.warning("[Server] Client heartbeat timeout (\(elapsed)s)")
                Task { await self.stopStreaming() }
                self.tcpChannel.disconnectConnection()
            }
        }
        timer.resume()
        heartbeatTimer = timer
        ERDLog.info("[Server] Heartbeat started")
    }

    private func stopHeartbeat() {
        heartbeatTimer?.cancel()
        heartbeatTimer = nil
    }

    private func handleAudioFrame(_ sampleBuffer: CMSampleBuffer) {
        guard isStreaming.value else { return }
        guard let blockBuffer = CMSampleBufferGetDataBuffer(sampleBuffer) else { return }

        var length = 0
        var dataPointer: UnsafeMutablePointer<Int8>?
        let status = CMBlockBufferGetDataPointer(blockBuffer, atOffset: 0, lengthAtOffsetOut: nil, totalLengthOut: &length, dataPointerOut: &dataPointer)

        guard status == noErr, let pointer = dataPointer, length > 0 else { return }

        let audioData = Data(bytes: pointer, count: length)

        // Send audioFrame packet over UDP for ultra-low latency system audio
        udpChannel.sendPacket(type: .audioFrame, payload: audioData)
    }
}

import Foundation
import CoreGraphics
import ApplicationServices

public class InputReceiver {
    private var screenWidth: CGFloat
    private var screenHeight: CGFloat

    public init(screenWidth: CGFloat, screenHeight: CGFloat) {
        self.screenWidth = screenWidth
        self.screenHeight = screenHeight
    }

    public func updateScreenSize(width: CGFloat, height: CGFloat) {
        self.screenWidth = width
        self.screenHeight = height
    }

    public func handleInputEvent(_ data: Data) {
        guard AXIsProcessTrusted() else { return }
        guard let event = InputEventPayload.deserialize(from: data) else { return }

        let x = CGFloat(event.x) * screenWidth
        let y = CGFloat(event.y) * screenHeight
        let point = CGPoint(x: x, y: y)

        let source = CGEventSource(stateID: .hidSystemState)

        switch event.type {
        case .mouseMove:
            post(.mouseMoved, at: point, button: .left, source: source)
        case .leftMouseDragged:
            post(.leftMouseDragged, at: point, button: .left, source: source)
        case .rightMouseDragged:
            post(.rightMouseDragged, at: point, button: .right, source: source)
        case .leftMouseDown:
            post(.leftMouseDown, at: point, button: .left, source: source)
        case .leftMouseUp:
            post(.leftMouseUp, at: point, button: .left, source: source)
        case .rightMouseDown:
            post(.rightMouseDown, at: point, button: .right, source: source)
        case .rightMouseUp:
            post(.rightMouseUp, at: point, button: .right, source: source)
        case .scrollWheel:
            if let cgEvent = CGEvent(scrollWheelEvent2Source: source, units: .pixel, wheelCount: 2,
                                     wheel1: Int32(event.scrollDeltaY), wheel2: Int32(event.scrollDeltaX), wheel3: 0) {
                cgEvent.post(tap: .cghidEventTap)
            }
        case .keyDown:
            postKey(code: event.keyCode, down: true, modifiers: event.modifiers, source: source)
        case .keyUp:
            postKey(code: event.keyCode, down: false, modifiers: event.modifiers, source: source)
        case .flagsChanged:
            if let cgEvent = CGEvent(keyboardEventSource: source, virtualKey: event.keyCode, keyDown: true) {
                var flags = CGEventFlags()
                if event.modifiers.contains(.shift)   { flags.insert(.maskShift) }
                if event.modifiers.contains(.control) { flags.insert(.maskControl) }
                if event.modifiers.contains(.option)  { flags.insert(.maskAlternate) }
                if event.modifiers.contains(.command) { flags.insert(.maskCommand) }
                if event.modifiers.contains(.capsLock) { flags.insert(.maskAlphaShift) }
                cgEvent.flags = flags
                cgEvent.post(tap: .cghidEventTap)
            }
        }
    }

    private func post(_ type: CGEventType, at point: CGPoint, button: CGMouseButton, source: CGEventSource?) {
        if let cgEvent = CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: button) {
            cgEvent.post(tap: .cghidEventTap)
        }
    }

    private func postKey(code: UInt16, down: Bool, modifiers: ModifierFlags, source: CGEventSource?) {
        if let cgEvent = CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(code), keyDown: down) {
            var flags = CGEventFlags()
            if modifiers.contains(.shift)   { flags.insert(.maskShift) }
            if modifiers.contains(.control) { flags.insert(.maskControl) }
            if modifiers.contains(.option)  { flags.insert(.maskAlternate) }
            if modifiers.contains(.command) { flags.insert(.maskCommand) }
            cgEvent.flags = flags
            cgEvent.post(tap: .cghidEventTap)
        }
    }
}

import Foundation
import ScreenCaptureKit
import CoreMedia
import CoreGraphics
import AppKit

public enum ScreenCaptureError: Error, Hashable {
    case noPermission
    case noDisplay
    case captureStartFailed
}

public class ScreenCapture: NSObject, SCStreamOutput, SCStreamDelegate {
    private var stream: SCStream?
    private let captureQueue = DispatchQueue(label: "eclipticrd.capture", qos: .userInteractive)
    private var display: SCDisplay?

    public var onFrame: ((CMSampleBuffer) -> Void)?
    public var onCursorPosition: ((CGPoint) -> Void)?
    public var onAudio: ((CMSampleBuffer) -> Void)?

    public private(set) var width: Int = 0
    public private(set) var height: Int = 0
    public private(set) var scaleFactor: CGFloat = 1.0

    public override init() { super.init() }

    public func getDisplayInfo() -> (width: Int, height: Int, pixelWidth: Int, pixelHeight: Int, scale: CGFloat) {
        let displayID = CGMainDisplayID()
        let w = CGDisplayPixelsWide(displayID)
        let h = CGDisplayPixelsHigh(displayID)
        let mode = CGDisplayCopyDisplayMode(displayID)
        let scale = CGFloat(mode?.pixelWidth ?? w) / CGFloat(w)
        let pw = Int(CGFloat(w) * scale)
        let ph = Int(CGFloat(h) * scale)
        return (w, h, pw, ph, scale)
    }

    public func start(fps: Int = ERDConstants.defaultFPS) async throws {
        // CGRequestScreenCaptureAccess() triggers the system prompt on first call.
        // On subsequent calls it returns the cached result without re-prompting.
        if !CGPreflightScreenCaptureAccess() {
            let granted = CGRequestScreenCaptureAccess()
            if !granted {
                // Open System Settings → Privacy → Screen Recording so the user
                // can manually toggle the permission (required for ad-hoc signed builds).
                if let url = URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_ScreenCapture") {
                    await MainActor.run { NSWorkspace.shared.open(url) }
                }
                throw ScreenCaptureError.noPermission
            }
        }

        let content = try await SCShareableContent.excludingDesktopWindows(false, onScreenWindowsOnly: true)
        guard let display = content.displays.first else { throw ScreenCaptureError.noDisplay }

        self.display = display
        let info = getDisplayInfo()
        self.width = info.width
        self.height = info.height
        self.scaleFactor = info.scale

        let filter = SCContentFilter(display: display, excludingApplications: [], exceptingWindows: [])
        let config = SCStreamConfiguration()
        config.width = info.pixelWidth
        config.height = info.pixelHeight
        config.minimumFrameInterval = CMTime(value: 1, timescale: CMTimeScale(fps))
        config.queueDepth = 5
        config.pixelFormat = kCVPixelFormatType_32BGRA
        config.showsCursor = true
        let hostAudioEnabled = UserDefaults.standard.object(forKey: "hostAudioEnabled") as? Bool ?? true
        config.capturesAudio = hostAudioEnabled

        let stream = SCStream(filter: filter, configuration: config, delegate: self)
        try stream.addStreamOutput(self, type: .screen, sampleHandlerQueue: captureQueue)
        if hostAudioEnabled {
            try stream.addStreamOutput(self, type: .audio, sampleHandlerQueue: captureQueue)
        }
        try await stream.startCapture()
        self.stream = stream
        ERDLog.video("[Capture] Started: \(width)x\(height) @\(fps)fps scale=\(scaleFactor)")
    }

    public func updateConfiguration(width: Int, height: Int, fps: Int) async throws {
        guard let stream = self.stream else {
            throw ScreenCaptureError.captureStartFailed
        }
        let config = SCStreamConfiguration()
        config.width = width
        config.height = height
        config.minimumFrameInterval = CMTime(value: 1, timescale: CMTimeScale(fps))
        config.queueDepth = 3
        config.pixelFormat = kCVPixelFormatType_32BGRA
        config.showsCursor = true

        try await stream.updateConfiguration(config)
        self.width = width
        self.height = height
        ERDLog.video("[Capture] Configuration updated: \(width)x\(height) @\(fps)fps")
    }

    public func stop() async throws {
        try await stream?.stopCapture()
        stream = nil
        ERDLog.video("[Capture] Stopped")
    }

    // MARK: - SCStreamOutput
    public func stream(_ stream: SCStream, didOutputSampleBuffer sampleBuffer: CMSampleBuffer, of type: SCStreamOutputType) {
        if type == .screen {
            onFrame?(sampleBuffer)

            // Try to extract cursor position from sample buffer attachments (private API).
            // Falls back to NSEvent.mouseLocation if the attachment is unavailable.
            if let cursor = CMGetAttachment(sampleBuffer, key: "com.apple.screencapture.cursor.position" as CFString, attachmentModeOut: nil) as? [String: Any],
               let x = cursor["x"] as? CGFloat, let y = cursor["y"] as? CGFloat {
                onCursorPosition?(CGPoint(x: x, y: y))
            } else {
                // Fallback: use NSEvent.mouseLocation (global screen coordinates, origin at bottom-left)
                // Convert to display-local coordinates accounting for multi-monitor offset
                let mouseLocation = NSEvent.mouseLocation
                if let screen = NSScreen.main {
                    let relativeX = mouseLocation.x - screen.frame.origin.x
                    let relativeY = screen.frame.maxY - mouseLocation.y
                    onCursorPosition?(CGPoint(x: relativeX, y: relativeY))
                }
            }
        } else if type == .audio {
            onAudio?(sampleBuffer)
        }
    }

    // MARK: - SCStreamDelegate
    public func stream(_ stream: SCStream, didStopWithError error: Error) {
        ERDLog.error("[Capture] Stream stopped with error: \(error)")
    }
}

import AppKit

public class InputSender {
    private let tcpChannel: TCPChannel
    private var captureView: NSView?
    private var localMonitor: Any?

    public init(tcpChannel: TCPChannel) {
        self.tcpChannel = tcpChannel
    }

    deinit { stopCapturing() }

    public func startCapturing(in view: NSView) {
        self.captureView = view

        let eventMask: NSEvent.EventTypeMask = [
            .mouseMoved, .leftMouseDown, .leftMouseUp, .rightMouseDown, .rightMouseUp,
            .leftMouseDragged, .rightMouseDragged, .scrollWheel,
            .keyDown, .keyUp, .flagsChanged
        ]

        localMonitor = NSEvent.addLocalMonitorForEvents(matching: eventMask) { [weak self] event in
            self?.handleEvent(event)
            return event
        }
    }

    public func stopCapturing() {
        if let m = localMonitor { NSEvent.removeMonitor(m); localMonitor = nil }
        captureView = nil
    }

    private func handleEvent(_ event: NSEvent) {
        guard let view = captureView else { return }

        let location = view.convert(event.locationInWindow, from: nil)
        let bounds = view.bounds
        guard bounds.width > 0, bounds.height > 0 else { return }

        let normX = Float(max(0, min(1, location.x / bounds.width)))
        let normY = Float(max(0, min(1, 1.0 - (location.y / bounds.height)))) // Flip Y

        var inputType: InputEventType
        var keyCode: UInt16 = 0
        var scrollDX: Float = 0
        var scrollDY: Float = 0

        switch event.type {
        case .mouseMoved:       inputType = .mouseMove
        case .leftMouseDown:    inputType = .leftMouseDown
        case .leftMouseUp:      inputType = .leftMouseUp
        case .rightMouseDown:   inputType = .rightMouseDown
        case .rightMouseUp:     inputType = .rightMouseUp
        case .leftMouseDragged: inputType = .leftMouseDragged
        case .rightMouseDragged: inputType = .rightMouseDragged
        case .scrollWheel:
            inputType = .scrollWheel
            scrollDX = Float(event.scrollingDeltaX)
            scrollDY = Float(event.scrollingDeltaY)
        case .keyDown:
            inputType = .keyDown
            keyCode = event.keyCode
        case .keyUp:
            inputType = .keyUp
            keyCode = event.keyCode
        case .flagsChanged:
            inputType = .flagsChanged
            keyCode = event.keyCode
        default: return
        }

        // Map NSEvent modifier flags
        var modifiers = ModifierFlags()
        if event.modifierFlags.contains(.shift)   { modifiers.insert(.shift) }
        if event.modifierFlags.contains(.control) { modifiers.insert(.control) }
        if event.modifierFlags.contains(.option)  { modifiers.insert(.option) }
        if event.modifierFlags.contains(.command) { modifiers.insert(.command) }
        if event.modifierFlags.contains(.capsLock) { modifiers.insert(.capsLock) }

        let payload = InputEventPayload(type: inputType, x: normX, y: normY, keyCode: keyCode,
                                         modifiers: modifiers, scrollDeltaX: scrollDX, scrollDeltaY: scrollDY)
        tcpChannel.sendInput(payload)
    }
}

import Foundation
import Network
import MetalKit
import AppKit

public class ClientCore {
    public static let shared = ClientCore()

    private let tcpChannel = TCPChannel()
    private let udpChannel = UDPChannel()
    private let frameReceiver = FrameReceiver()
    private let decoder = VideoDecoder()
    private let audioPlayer = ClientAudioPlayer()
    public let isAudioMuted = AtomicBool(false)
    private var renderer: MetalRenderer?
    private var inputSender: InputSender?
    // Protects inputSender from concurrent access between TCP callbacks and UI thread.
    private let stateQueue = DispatchQueue(label: "eclipticrd.client.state")

    private var abrTimer: DispatchSourceTimer?
    private let abrQueue = DispatchQueue(label: "eclipticrd.client.abr")
    private var currentBitrate: Int = ERDConstants.defaultBitrate
    private var lowLossStartTime: Date?

    private var clipboardMonitor: ClipboardMonitor?
    private var peerCapabilities: HandshakeCapabilities = []
    private var nextStreamConfigRequestID: UInt32 = 1
    public var onStreamConfigResponse: (@Sendable (StreamConfigurationResponsePayload) -> Void)?
    public var onStreamConfigRejected: (@Sendable (StreamConfigurationRejectPayload) -> Void)?
    public var onStreamConfigError: (@Sendable (StreamConfigurationErrorPayload) -> Void)?

    public var onSessionReady: (@Sendable () -> Void)?
    public var onServerIdentity: (@Sendable (String) -> Void)?
    public var onDisconnected: (@Sendable () -> Void)?
    public var onError: (@Sendable (String) -> Void)?
    public var onClipboardSynced: (@Sendable (String) -> Void)?

    public var serverHost: String?
    private var udpTargetHost: String?
    private var _serverScreenWidth: Int = 0
    private var _serverScreenHeight: Int = 0
    public var serverScreenWidth: Int {
        get { stateQueue.sync { _serverScreenWidth } }
        set { stateQueue.sync { _serverScreenWidth = newValue } }
    }
    public var serverScreenHeight: Int {
        get { stateQueue.sync { _serverScreenHeight } }
        set { stateQueue.sync { _serverScreenHeight = newValue } }
    }

    private init() {
        // Wire pipeline: UDP → FrameReceiver → VideoDecoder → MetalRenderer
        udpChannel.onReceive = { [weak self] data, endpoint in
            guard let self = self else { return }
            guard data.count >= ERDConstants.packetHeaderSize else { return }

            // Bypass frame assembly queue for zero-jitter, real-time audio playback
            if data[2] == PacketType.audioFrame.rawValue {
                if !self.isAudioMuted.value {
                    let payload = data.subdata(in: ERDConstants.packetHeaderSize..<data.count)
                    self.audioPlayer.play(data: payload)
                }
            } else {
                self.frameReceiver.handlePacket(data)
            }
        }

        frameReceiver.onFrameReady = { [weak self] data, header in
            self?.serverScreenWidth = Int(header.width)
            self?.serverScreenHeight = Int(header.height)
            self?.decoder.decode(data)
        }

        frameReceiver.onCursorUpdate = { [weak self] cursor in
            self?.renderer?.updateCursor(x: cursor.x, y: cursor.y)
        }

        decoder.onDecodedFrame = { [weak self] pixelBuffer in
            self?.renderer?.displayFrame(pixelBuffer)
        }
    }

    // MARK: - Connection Methods

    /// Connect via direct IP (LAN manual)
    public func start(host: String?) {
        guard let host = host else { return }
        self.serverHost = host
        ERDLog.info("[Client] Connecting to \(host)")

        tcpChannel.connect(host: host, port: ERDConstants.tcpPort)
        setupTCPHandlers(host: host)
    }

    /// Connect via Bonjour endpoint
    public func start(endpoint: NWEndpoint, name: String) {
        ERDLog.info("[Client] Connecting to Bonjour Endpoint: \(name)")
        tcpChannel.connect(to: endpoint)
        setupTCPHandlers(host: nil)
    }

    /// Connect via PIN (Internet / NAT traversal)
    public func startICE(pin: String) {
        Task {
            do {
                // 1. Get our public IP via STUN
                let stun = STUNClient()
                let (publicIP, publicPort) = try await stun.fetchPublicIP()
                ERDLog.info("[ClientCore] STUN Public IP: \(publicIP):\(publicPort)")

                // 2. Get local IP
                let localIP = NetworkUtils.getLocalIP() ?? "127.0.0.1"
                let localPort = ERDConstants.tcpPort

                // 3. Exchange candidates via ntfy.sh
                let signaling = SignalingClient(pin: pin, role: "client")
                let ourCandidate = SessionCandidate(role: "client", localIP: localIP, localPort: localPort,
                                                     publicIP: publicIP, publicPort: publicPort)

                ERDLog.info("[ClientCore] Waiting for server candidate via ntfy.sh...")
                let serverCandidate = try await signaling.exchangeCandidate(ourCandidate)
                ERDLog.info("[ClientCore] Retrieved Server Candidate: \(serverCandidate.publicIP):\(serverCandidate.publicPort)")
                signaling.stop()

                // 4. Try ICE: connect to both local and public IP
                var endpoints: [NWEndpoint] = []

                // Local IP endpoint
                if let port = NWEndpoint.Port(rawValue: serverCandidate.localPort) {
                    endpoints.append(.hostPort(host: NWEndpoint.Host(serverCandidate.localIP), port: port))
                }
                // Public IP endpoint
                if let port = NWEndpoint.Port(rawValue: serverCandidate.publicPort) {
                    endpoints.append(.hostPort(host: NWEndpoint.Host(serverCandidate.publicIP), port: port))
                }

                tcpChannel.connectICE(endpoints: endpoints)
                // Pass nil so the onConnect handler resolves host from
                // the actual winning TCP connection (local or public).
                setupTCPHandlers(host: nil)

            } catch {
                ERDLog.error("[ClientCore] ICE connection failed: \(error)")
                self.onError?("ICE connection failed: \(error.localizedDescription)")
            }
        }
    }

    public func stop() {
        stopClipboardSync()
        stopABR()
        stateQueue.sync {
            inputSender?.stopCapturing()
            inputSender = nil
        }
        frameReceiver.stop()
        decoder.stop()
        audioPlayer.stop()
        serverHost = nil
        udpTargetHost = nil
        serverScreenWidth = 0
        serverScreenHeight = 0
        tcpChannel.stop()
        udpChannel.stop()
        ERDLog.info("[Client] Disconnected from server")
    }

    // MARK: - Internal

    private func setupTCPHandlers(host: String?) {
        tcpChannel.onConnect = { [weak self] in
            guard let self = self else { return }

            // Resolve server IP for UDP
            let resolvedHost = host ?? self.tcpChannel.remoteHostIP ?? "127.0.0.1"
            self.serverHost = resolvedHost
            self.udpTargetHost = resolvedHost

            if host == nil {
                ERDLog.info("[Client] Resolved server IP: \(resolvedHost)")
            }

            ERDLog.info("[Client] TCP connected, sending handshake...")
            let hs = HandshakePayload(hostname: ProcessInfo.processInfo.hostName,
                                       screenWidth: 0, screenHeight: 0, scaleFactor: 1.0,
                                       capabilities: [.streamConfiguration, .textClipboardSync])
            let header = PacketHeader(type: .handshake, sequence: 0, timestamp: 0)
            var packet = header.serialize()
            packet.append(hs.serialize())
            self.tcpChannel.send(packet)
        }

        tcpChannel.onReceive = { [weak self] data in
            guard let self = self else { return }
            guard data.count >= ERDConstants.packetHeaderSize else {
                return
            }
            guard let header = PacketHeader.deserialize(from: data) else {
                return
            }
            let payload = data.subdata(in: ERDConstants.packetHeaderSize..<data.count)

            if header.type == .handshakeAck {
                if let hs = HandshakePayload.deserialize(from: payload) {
                    ERDLog.info("[Client] Server: \(hs.hostname) \(hs.screenWidth)x\(hs.screenHeight) caps=\(hs.capabilities.rawValue)")
                    self.onServerIdentity?(hs.hostname)
                    self.serverScreenWidth = Int(hs.screenWidth)
                    self.serverScreenHeight = Int(hs.screenHeight)
                    self.stateQueue.sync { self.peerCapabilities = hs.capabilities }

                    let udpHost = self.udpTargetHost ?? self.serverHost ?? "127.0.0.1"
                    self.udpChannel.onReady = { [weak self] in
                        self?.udpChannel.sendPing()
                    }
                    self.udpChannel.connect(host: udpHost, port: ERDConstants.udpPort)
                    ERDLog.info("[Client] Connecting UDP to \(udpHost):\(ERDConstants.udpPort)")
                    self.startABR()
                    self.startClipboardSync()
                    self.audioPlayer.start()
                    self.onSessionReady?()
                }
            } else if header.type == .control {
                if let msg = ControlMessage.deserialize(from: payload) {
                    switch msg.type {
                    case .ping:
                        self.tcpChannel.sendControl(ControlMessage(type: .pong))
                    case .streamConfigResponse:
                        if let data = msg.payload,
                           let resp = StreamConfigurationResponsePayload.deserialize(from: data) {
                            ERDLog.info("[Client] Stream config accepted: \(resp.activeConfiguration.width)x\(resp.activeConfiguration.height)")
                            self.onStreamConfigResponse?(resp)
                        }
                    case .streamConfigReject:
                        if let data = msg.payload,
                           let reject = StreamConfigurationRejectPayload.deserialize(from: data) {
                            ERDLog.warning("[Client] Stream config rejected: \(reject.message)")
                            self.onStreamConfigRejected?(reject)
                        }
                    case .streamConfigError:
                        if let data = msg.payload,
                           let err = StreamConfigurationErrorPayload.deserialize(from: data) {
                            ERDLog.error("[Client] Stream config error: \(err.message)")
                            self.onStreamConfigError?(err)
                        }
                    case .clipboardSyncUpdate:
                        if let data = msg.payload,
                           let update = ClipboardSyncUpdatePayload.deserialize(from: data) {
                            self.handleClipboardUpdate(update)
                        }
                    case .clipboardSyncError:
                        if let data = msg.payload,
                           let err = ClipboardSyncErrorPayload.deserialize(from: data) {
                            ERDLog.warning("[Client] Clipboard sync error: \(err.message)")
                        }
                    default: break
                    }
                }
            }
        }

        tcpChannel.onDisconnect = { [weak self] in
            ERDLog.info("[Client] Disconnected from server")
            self?.onDisconnected?()
            self?.stop()
        }
    }

    public func setupRenderer(mtkView: MTKView) {
        renderer = MetalRenderer(mtkView: mtkView)
    }

    public func startInput(in view: NSView) {
        let sender = InputSender(tcpChannel: tcpChannel)
        sender.startCapturing(in: view)
        stateQueue.sync { inputSender = sender }
    }

    // MARK: - Stream Configuration

    public func requestStreamConfiguration(_ config: StreamConfiguration) {
        let requestID = stateQueue.sync { () -> UInt32 in
            let id = nextStreamConfigRequestID
            nextStreamConfigRequestID += 1
            return id
        }
        let request = StreamConfigurationRequestPayload(requestID: requestID, desiredConfiguration: config)
        let msg = ControlMessage(type: .streamConfigRequest, payload: request.serialize())
        tcpChannel.sendControl(msg)
        ERDLog.info("[Client] Requesting stream config: \(config.width)x\(config.height) @\(config.framesPerSecond)fps")
    }

    // MARK: - Clipboard Sync

    private func startClipboardSync() {
        let peerCaps = stateQueue.sync { self.peerCapabilities }
        guard peerCaps.contains(.textClipboardSync) else {
            ERDLog.info("[Client] Server does not support clipboard sync, skipping")
            return
        }

        let monitor = ClipboardMonitor { [weak self] text in
            guard let self = self else { return }
            let update = ClipboardSyncUpdatePayload(
                requestID: 0,
                direction: .clientToHost,
                origin: .localPasteboard,
                text: text)
            if let data = update.serialize() {
                let msg = ControlMessage(type: .clipboardSyncUpdate, payload: data)
                self.tcpChannel.sendControl(msg)
            }
        }
        stateQueue.sync { self.clipboardMonitor = monitor }
        monitor.start()
        ERDLog.info("[Client] Clipboard sync started")
    }

    private func stopClipboardSync() {
        let monitor = stateQueue.sync { self.clipboardMonitor }
        monitor?.stop()
        stateQueue.sync { self.clipboardMonitor = nil }
    }

    private func handleClipboardUpdate(_ update: ClipboardSyncUpdatePayload) {
        let monitor = stateQueue.sync { self.clipboardMonitor }
        monitor?.applyRemoteText(update.text)
        ERDLog.info("[Client] Clipboard received from server (\(update.text.count) chars)")
        onClipboardSynced?(update.text)
    }

    // MARK: - Adaptive Bitrate

    private func startABR() {
        stopABR()
        currentBitrate = ERDConstants.defaultBitrate
        lowLossStartTime = nil

        let timer = DispatchSource.makeTimerSource(queue: abrQueue)
        timer.schedule(deadline: .now() + 3.0, repeating: 3.0)
        timer.setEventHandler { [weak self] in
            self?.evaluateBitrate()
        }
        timer.resume()
        abrTimer = timer
    }

    private func stopABR() {
        abrTimer?.cancel()
        abrTimer = nil
    }

    private func evaluateBitrate() {
        let lossRatio = frameReceiver.frameLossRatio
        var newBitrate = currentBitrate

        if lossRatio > 0.10 {
            lowLossStartTime = nil
            newBitrate = max(ERDConstants.minBitrate, Int(Double(currentBitrate) * 0.75))
            ERDLog.info("[Client] ABR: loss \(String(format: "%.1f", lossRatio * 100))%% → reduce to \(newBitrate)")
        } else if lossRatio < 0.02 {
            if let start = lowLossStartTime {
                if Date().timeIntervalSince(start) >= 10.0 {
                    newBitrate = min(ERDConstants.maxBitrate, Int(Double(currentBitrate) * 1.10))
                    lowLossStartTime = Date()
                    ERDLog.info("[Client] ABR: stable → increase to \(newBitrate)")
                }
            } else {
                lowLossStartTime = Date()
            }
        } else {
            lowLossStartTime = nil
        }

        if newBitrate != currentBitrate {
            currentBitrate = newBitrate
            let payload = BitrateAdjustPayload(targetBitrate: Int32(newBitrate))
            let msg = ControlMessage(type: .bitrateAdjust, payload: payload.serialize())
            tcpChannel.sendControl(msg)
        }
    }

    public struct StreamStats {
        public let fps: Double
        public let bitrate: Int
        public let frameLoss: Double
        public let framesReceived: Int
    }

    public func getStats() -> StreamStats {
        StreamStats(
            fps: frameReceiver.recentFPS,
            bitrate: currentBitrate,
            frameLoss: frameReceiver.frameLossRatio,
            framesReceived: frameReceiver.totalFramesReceived
        )
    }
}

