import Foundation

public enum NetworkUtils {
    /// Returns the local IPv4 address of a non-loopback network interface.
    /// Prefers en0 (WiFi) and en1 (Ethernet), but falls back to any active "en" interface
    /// to support USB-C adapters and other configurations.
    public static func getLocalIP() -> String? {
        var ifaddr: UnsafeMutablePointer<ifaddrs>?
        guard getifaddrs(&ifaddr) == 0, let firstAddr = ifaddr else { return nil }
        defer { freeifaddrs(ifaddr) }

        var preferred: String?
        var fallback: String?

        for ptr in sequence(first: firstAddr, next: { $0.pointee.ifa_next }) {
            let sa = ptr.pointee.ifa_addr.pointee
            guard sa.sa_family == UInt8(AF_INET) else { continue }
            let name = String(cString: ptr.pointee.ifa_name)
            guard name.hasPrefix("en") else { continue }

            var hostname = [CChar](repeating: 0, count: Int(NI_MAXHOST))
            getnameinfo(ptr.pointee.ifa_addr, socklen_t(sa.sa_len),
                        &hostname, socklen_t(hostname.count), nil, 0, NI_NUMERICHOST)
            let ip = String(cString: hostname)

            if name == "en0" || name == "en1" {
                preferred = ip
                break
            } else if fallback == nil {
                fallback = ip
            }
        }
        return preferred ?? fallback
    }
}

import Foundation
import VideoToolbox
import CoreMedia

public enum VideoEncoderError: Error {
    case sessionCreationFailed
    case encodingFailed
}

public class VideoEncoder {
    private var session: VTCompressionSession?
    private let encoderQueue = DispatchQueue(label: "eclipticrd.encoder", qos: .userInteractive)
    private static let queueKey = DispatchSpecificKey<Bool>()
    private var frameCount: Int64 = 0
    private var retainedSelf: Unmanaged<VideoEncoder>?

    private let width: Int
    private let height: Int
    private let bitrate: Int
    private let fps: Int
    private var pendingForceKeyFrame = AtomicBool(false)

    public var onEncodedFrame: ((Data, Bool) -> Void)?

    public init(width: Int, height: Int, bitrate: Int = ERDConstants.defaultBitrate, fps: Int = ERDConstants.defaultFPS) {
        self.width = width; self.height = height; self.bitrate = bitrate; self.fps = fps
        encoderQueue.setSpecific(key: Self.queueKey, value: true)
    }

    deinit { stop() }

    public func start() throws {
        retainedSelf = Unmanaged.passRetained(self)

        let err = VTCompressionSessionCreate(
            allocator: kCFAllocatorDefault,
            width: Int32(width), height: Int32(height),
            codecType: kCMVideoCodecType_HEVC,
            encoderSpecification: nil, imageBufferAttributes: nil, compressedDataAllocator: nil,
            outputCallback: encoderCallback,
            refcon: retainedSelf!.toOpaque(),
            compressionSessionOut: &session
        )
        guard err == noErr, let session = session else { throw VideoEncoderError.sessionCreationFailed }

        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_RealTime, value: kCFBooleanTrue)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_AllowFrameReordering, value: kCFBooleanFalse)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_AverageBitRate, value: bitrate as CFTypeRef)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_MaxKeyFrameInterval, value: ERDConstants.keyFrameInterval as CFTypeRef)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_ExpectedFrameRate, value: fps as CFTypeRef)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_ProfileLevel, value: kVTProfileLevel_HEVC_Main_AutoLevel)

        VTCompressionSessionPrepareToEncodeFrames(session)
        ERDLog.video("[Encoder] Started: H.265 \(width)x\(height) @\(bitrate/1_000_000)Mbps")
    }

    public func stop() {
        let work = {
            if let session = self.session {
                VTCompressionSessionInvalidate(session)
                self.session = nil
            }
            self.retainedSelf?.release()
            self.retainedSelf = nil
            self.frameCount = 0
            ERDLog.video("[Encoder] Stopped")
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            encoderQueue.sync { work() }
        }
    }

    public func encode(_ sampleBuffer: CMSampleBuffer) {
        encoderQueue.async { [weak self] in
            guard let self = self else { return }
            guard let session = self.session else { return }
            guard let imageBuffer = CMSampleBufferGetImageBuffer(sampleBuffer) else {
                return
            }
            let pts = CMTime(value: self.frameCount, timescale: CMTimeScale(self.fps))
            self.frameCount += 1

            var frameProps: CFDictionary? = nil
            if self.pendingForceKeyFrame.value {
                self.pendingForceKeyFrame.value = false
                frameProps = [kVTEncodeFrameOptionKey_ForceKeyFrame: true] as CFDictionary
            }

            VTCompressionSessionEncodeFrame(session, imageBuffer: imageBuffer, presentationTimeStamp: pts,
                                            duration: .invalid, frameProperties: frameProps, sourceFrameRefcon: nil, infoFlagsOut: nil)
        }
    }

    public func forceKeyFrame() {
        pendingForceKeyFrame.value = true
    }

    public func updateBitrate(_ newBitrate: Int) {
        encoderQueue.async { [weak self] in
            guard let self = self, let session = self.session else { return }
            VTSessionSetProperty(session, key: kVTCompressionPropertyKey_AverageBitRate, value: newBitrate as CFTypeRef)
        }
    }

    public func updateFPS(_ newFPS: Int) {
        encoderQueue.async { [weak self] in
            guard let self = self, let session = self.session else { return }
            VTSessionSetProperty(session, key: kVTCompressionPropertyKey_ExpectedFrameRate, value: newFPS as CFTypeRef)
        }
    }

    fileprivate func handleEncodedFrame(_ sampleBuffer: CMSampleBuffer) {
        guard let dataBuffer = CMSampleBufferGetDataBuffer(sampleBuffer) else { return }

        let isKeyFrame: Bool = {
            guard let attachments = CMSampleBufferGetSampleAttachmentsArray(sampleBuffer, createIfNecessary: false) as? [[CFString: Any]],
                  let first = attachments.first else { return true }
            return !(first[kCMSampleAttachmentKey_NotSync] as? Bool ?? false)
        }()

        var length = 0
        var dataPointer: UnsafeMutablePointer<Int8>?
        CMBlockBufferGetDataPointer(dataBuffer, atOffset: 0, lengthAtOffsetOut: nil, totalLengthOut: &length, dataPointerOut: &dataPointer)

        guard let pointer = dataPointer, length > 0 else { return }

        var frameData = Data()

        // For keyframes, prepend VPS/SPS/PPS from the format description
        // so the decoder can create its decoding session.
        if isKeyFrame, let formatDesc = CMSampleBufferGetFormatDescription(sampleBuffer) {
            var paramCount: Int = 0
            CMVideoFormatDescriptionGetHEVCParameterSetAtIndex(formatDesc, parameterSetIndex: 0,
                parameterSetPointerOut: nil, parameterSetSizeOut: nil, parameterSetCountOut: &paramCount, nalUnitHeaderLengthOut: nil)

            for i in 0..<paramCount {
                var paramPtr: UnsafePointer<UInt8>?
                var paramSize: Int = 0
                let status = CMVideoFormatDescriptionGetHEVCParameterSetAtIndex(formatDesc, parameterSetIndex: i,
                    parameterSetPointerOut: &paramPtr, parameterSetSizeOut: &paramSize, parameterSetCountOut: nil, nalUnitHeaderLengthOut: nil)
                if status == noErr, let ptr = paramPtr, paramSize > 0 {
                    // Write 4-byte AVCC length prefix + parameter set data
                    var len = UInt32(paramSize).bigEndian
                    frameData.append(Data(bytes: &len, count: 4))
                    frameData.append(Data(bytes: ptr, count: paramSize))
                }
            }
        }

        frameData.append(Data(bytes: pointer, count: length))
        onEncodedFrame?(frameData, isKeyFrame)
    }
}

private func encoderCallback(outputCallbackRefCon: UnsafeMutableRawPointer?,
                              sourceFrameRefCon: UnsafeMutableRawPointer?,
                              status: OSStatus,
                              infoFlags: VTEncodeInfoFlags,
                              sampleBuffer: CMSampleBuffer?) {
    guard status == noErr, let sampleBuffer = sampleBuffer, let refcon = outputCallbackRefCon else { return }
    let encoder = Unmanaged<VideoEncoder>.fromOpaque(refcon).takeUnretainedValue()
    encoder.handleEncodedFrame(sampleBuffer)
}

import Foundation

public class FrameSender {
    private let udpChannel: UDPChannel
    private var frameIdCounter: UInt32 = 0
    private let counterLock = NSLock()

    public init(udpChannel: UDPChannel) {
        self.udpChannel = udpChannel
    }

    public func sendFrame(data: Data, width: Int, height: Int, isKeyFrame: Bool) {
        counterLock.lock()
        frameIdCounter += 1
        let frameId = frameIdCounter
        counterLock.unlock()

        let maxPayload = ERDConstants.maxPayloadSize - FrameChunkPayload.headerSize
        let totalChunks = UInt16((data.count + maxPayload - 1) / maxPayload)

        guard totalChunks <= ERDConstants.maxChunksPerFrame else {
            ERDLog.error("[FrameSender] Frame too large: \(data.count) bytes, \(totalChunks) chunks")
            return
        }

        // 1. Send frame header via UDP
        let header = FrameHeaderPayload(
            frameId: frameId, width: UInt16(width), height: UInt16(height),
            isKeyFrame: isKeyFrame, totalChunks: totalChunks, totalSize: UInt32(data.count)
        )
        udpChannel.sendPacket(type: .frameHeader, payload: header.serialize())

        // 2. Send frame chunks via UDP
        var offset = 0
        var chunkIndex: UInt16 = 0
        while offset < data.count {
            let end = min(offset + maxPayload, data.count)
            let chunkData = data.subdata(in: offset..<end)
            let chunk = FrameChunkPayload(frameId: frameId, chunkIndex: chunkIndex, chunkData: chunkData)
            udpChannel.sendPacket(type: .frameChunk, payload: chunk.serialize())
            offset = end
            chunkIndex += 1
        }
    }

    public func sendCursorUpdate(x: Float, y: Float, cursorType: UInt8 = 0) {
        let cursor = CursorUpdate(x: x, y: y, cursorType: cursorType)
        udpChannel.sendPacket(type: .cursorUpdate, payload: cursor.serialize())
    }
}

import Foundation

public class FrameReceiver {
    private struct FrameAssembly {
        let header: FrameHeaderPayload
        var chunks: [UInt16: Data]
        let startTime: Date

        var isComplete: Bool { chunks.count == Int(header.totalChunks) }

        func assemble() -> Data? {
            guard isComplete else { return nil }
            var result = Data(capacity: Int(header.totalSize))
            for i in 0..<header.totalChunks {
                guard let chunk = chunks[i] else { return nil }
                result.append(chunk)
            }
            return result
        }
    }

    private struct LossEntry {
        let timestamp: Date
        let lost: Int
        let total: Int
    }

    private var frames: [UInt32: FrameAssembly] = [:]
    private let assemblyQueue = DispatchQueue(label: "eclipticrd.frame-assembly", qos: .userInteractive)
    private var cleanupTimer: DispatchSourceTimer?
    private let timeout: Double = ERDConstants.frameAssemblyTimeout

    private var expectedFrameId: UInt32 = 0
    private var hasReceivedFirstFrame = false
    private var lossEntries: [LossEntry] = []
    private let lossLock = NSLock()

    private var completedFrameTimestamps: [Date] = []
    public private(set) var totalFramesReceived: Int = 0

    public var onFrameReady: ((Data, FrameHeaderPayload) -> Void)?
    public var onCursorUpdate: ((CursorUpdate) -> Void)?

    /// Computed property: FPS based on frames completed in the last 1 second
    public var recentFPS: Double {
        assemblyQueue.sync {
            let cutoff = Date().addingTimeInterval(-1.0)
            let recentCount = completedFrameTimestamps.filter { $0 > cutoff }.count
            return Double(recentCount)
        }
    }

    public var frameLossRatio: Double {
        lossLock.lock()
        defer { lossLock.unlock() }
        let cutoff = Date().addingTimeInterval(-5.0)
        let recent = lossEntries.filter { $0.timestamp > cutoff }
        let totalLost = recent.reduce(0) { $0 + $1.lost }
        let totalFrames = recent.reduce(0) { $0 + $1.total }
        guard totalFrames > 0 else { return 0.0 }
        return Double(totalLost) / Double(totalFrames)
    }

    public init() {
        startCleanupTimer()
    }

    deinit {
        let timer = cleanupTimer
        assemblyQueue.async {
            timer?.cancel()
        }
    }

    public func stop() {
        assemblyQueue.sync {
            self.cleanupTimer?.cancel()
            self.cleanupTimer = nil
            self.frames.removeAll()
            self.completedFrameTimestamps.removeAll()
            self.totalFramesReceived = 0
            self.expectedFrameId = 0
            self.startCleanupTimer()
        }
        lossLock.lock()
        lossEntries.removeAll()
        hasReceivedFirstFrame = false
        lossLock.unlock()
    }

    public func handlePacket(_ data: Data) {
        guard data.count >= ERDConstants.packetHeaderSize else { return }
        guard let header = PacketHeader.deserialize(from: data) else { return }
        let payload = data.subdata(in: ERDConstants.packetHeaderSize..<data.count)

        assemblyQueue.async { [weak self] in
            switch header.type {
            case .frameHeader:
                self?.handleFrameHeader(payload)
            case .frameChunk:
                self?.handleFrameChunk(payload)
            case .cursorUpdate:
                if let cursor = CursorUpdate.deserialize(from: payload) {
                    self?.onCursorUpdate?(cursor)
                }
            default: break
            }
        }
    }

    private func handleFrameHeader(_ data: Data) {
        guard let fh = FrameHeaderPayload.deserialize(from: data) else {
            ERDLog.error("[FrameReceiver] Failed to deserialize frame header from \(data.count) bytes")
            return
        }

        if fh.isKeyFrame {
            let keysToRemove = frames.keys.filter { $0 < fh.frameId }
            for key in keysToRemove {
                if let assembly = frames[key], !assembly.isComplete {
                    frames.removeValue(forKey: key)
                }
            }
        }

        trackFrameLoss(receivedFrameId: fh.frameId)
        frames[fh.frameId] = FrameAssembly(header: fh, chunks: [:], startTime: Date())
    }

    private func handleFrameChunk(_ data: Data) {
        guard let chunk = FrameChunkPayload.deserialize(from: data) else {
            ERDLog.error("[FrameReceiver] Failed to deserialize chunk from \(data.count) bytes")
            return
        }
        guard frames[chunk.frameId] != nil else {
            ERDLog.debug("[FrameReceiver] Orphan chunk: frame#\(chunk.frameId) idx=\(chunk.chunkIndex) (no header yet)")
            return
        }

        frames[chunk.frameId]!.chunks[chunk.chunkIndex] = chunk.chunkData
        let assembly = frames[chunk.frameId]!

        if assembly.isComplete {
            let completed = frames.removeValue(forKey: chunk.frameId)!
            if let frameData = completed.assemble() {
                ERDLog.video("[FrameReceiver] ✅ Frame #\(chunk.frameId) assembled: \(frameData.count) bytes")
                totalFramesReceived += 1
                completedFrameTimestamps.append(Date())
                let cutoff = Date().addingTimeInterval(-2.0)
                completedFrameTimestamps.removeAll { $0 < cutoff }
                onFrameReady?(frameData, completed.header)
            }
        }
    }

    private func trackFrameLoss(receivedFrameId: UInt32) {
        lossLock.lock()
        defer { lossLock.unlock() }

        if !hasReceivedFirstFrame {
            hasReceivedFirstFrame = true
            expectedFrameId = receivedFrameId + 1
            lossEntries.append(LossEntry(timestamp: Date(), lost: 0, total: 1))
            return
        }

        let gap = receivedFrameId > expectedFrameId ? Int(receivedFrameId - expectedFrameId) : 0
        lossEntries.append(LossEntry(timestamp: Date(), lost: gap, total: 1 + gap))
        expectedFrameId = receivedFrameId + 1

        let cutoff = Date().addingTimeInterval(-10.0)
        lossEntries.removeAll { $0.timestamp < cutoff }
    }

    private func startCleanupTimer() {
        let timer = DispatchSource.makeTimerSource(queue: assemblyQueue)
        timer.schedule(deadline: .now() + 1.0, repeating: 1.0)
        timer.setEventHandler { [weak self] in
            guard let self = self else { return }
            let now = Date()
            self.frames = self.frames.filter { now.timeIntervalSince($0.value.startTime) < self.timeout }
        }
        timer.resume()
        cleanupTimer = timer
    }
}

import Foundation
import VideoToolbox
import CoreMedia

public class VideoDecoder {
    private var session: VTDecompressionSession?
    private var formatDescription: CMVideoFormatDescription?
    private let decoderQueue = DispatchQueue(label: "eclipticrd.decoder", qos: .userInteractive)
    private var retainedSelf: Unmanaged<VideoDecoder>?

    private var sps: Data?
    private var pps: Data?
    private var vps: Data?

    public var onDecodedFrame: ((CVPixelBuffer) -> Void)?

    public init() {}

    // NOTE: Do not call stop() from deinit — decoderQueue.sync would deadlock
    // if the last reference is released on decoderQueue itself.
    // Callers must call stop() explicitly before releasing.

    public func decode(_ data: Data) {
        decoderQueue.async { [weak self] in
            guard let self = self else { return }
            self.processNALUs(data)
        }
    }

    public func stop() {
        decoderQueue.sync {
            if let session = self.session {
                VTDecompressionSessionInvalidate(session)
                self.session = nil
            }
            self.retainedSelf?.release()
            self.retainedSelf = nil
            self.formatDescription = nil
            self.sps = nil; self.pps = nil; self.vps = nil
        }
    }

    private func processNALUs(_ data: Data) {
        // HEVC NALUs use 4-byte length prefix (AVCC format from VideoToolbox output)
        var offset = 0
        while offset + 4 <= data.count {
            let naluLength = data.subdata(in: offset..<offset+4).withUnsafeBytes { $0.load(as: UInt32.self).bigEndian }
            offset += 4
            guard naluLength > 0, offset + Int(naluLength) <= data.count else { break }

            let nalu = data.subdata(in: offset..<offset+Int(naluLength))
            let naluType = (nalu[0] >> 1) & 0x3F // HEVC NAL unit type

            switch naluType {
            case 32: // VPS
                vps = nalu
            case 33: // SPS
                sps = nalu
            case 34: // PPS
                pps = nalu
                createDecoderIfNeeded()
            default:
                // IDR (19, 20) or non-IDR (0, 1) - decode it
                if naluType <= 31 || naluType == 19 || naluType == 20 {
                    decodeNALU(nalu)
                }
            }
            offset += Int(naluLength)
        }
    }

    private func createDecoderIfNeeded() {
        guard let vps = vps, let sps = sps, let pps = pps else { return }

        // Nest withUnsafeBytes calls to keep pointers valid for the entire scope.
        var newFormat: CMVideoFormatDescription?
        vps.withUnsafeBytes { vpsBuffer in
            sps.withUnsafeBytes { spsBuffer in
                pps.withUnsafeBytes { ppsBuffer in
                    let pointers: [UnsafePointer<UInt8>] = [
                        vpsBuffer.baseAddress!.assumingMemoryBound(to: UInt8.self),
                        spsBuffer.baseAddress!.assumingMemoryBound(to: UInt8.self),
                        ppsBuffer.baseAddress!.assumingMemoryBound(to: UInt8.self)
                    ]
                    let sizes = [vps.count, sps.count, pps.count]

                    CMVideoFormatDescriptionCreateFromHEVCParameterSets(
                        allocator: kCFAllocatorDefault,
                        parameterSetCount: 3,
                        parameterSetPointers: pointers,
                        parameterSetSizes: sizes,
                        nalUnitHeaderLength: 4,
                        extensions: nil,
                        formatDescriptionOut: &newFormat
                    )
                }
            }
        }

        guard let format = newFormat else { return }

        if session != nil {
            VTDecompressionSessionInvalidate(session!)
            session = nil
        }
        retainedSelf?.release()
        retainedSelf = Unmanaged.passRetained(self)
        formatDescription = format

        let pixelBufferAttributes: [String: Any] = [
            kCVPixelBufferPixelFormatTypeKey as String: kCVPixelFormatType_32BGRA,
            kCVPixelBufferMetalCompatibilityKey as String: true
        ]

        var callbackRecord = VTDecompressionOutputCallbackRecord(
            decompressionOutputCallback: decoderCallback,
            decompressionOutputRefCon: retainedSelf!.toOpaque()
        )

        VTDecompressionSessionCreate(
            allocator: kCFAllocatorDefault,
            formatDescription: format,
            decoderSpecification: nil,
            imageBufferAttributes: pixelBufferAttributes as CFDictionary,
            outputCallback: &callbackRecord,
            decompressionSessionOut: &session
        )
    }

    private func decodeNALU(_ nalu: Data) {
        guard let session = session, let format = formatDescription else { return }

        // Wrap NALU with 4-byte length prefix
        var length = UInt32(nalu.count).bigEndian
        var blockData = Data(bytes: &length, count: 4)
        blockData.append(nalu)

        var blockBuffer: CMBlockBuffer?
        let totalLength = blockData.count

        blockData.withUnsafeBytes { rawBuffer in
            guard let baseAddress = rawBuffer.baseAddress else { return }
            CMBlockBufferCreateWithMemoryBlock(
                allocator: kCFAllocatorDefault,
                memoryBlock: nil, blockLength: totalLength,
                blockAllocator: nil, customBlockSource: nil,
                offsetToData: 0, dataLength: totalLength,
                flags: 0, blockBufferOut: &blockBuffer)

            if let block = blockBuffer {
                CMBlockBufferReplaceDataBytes(with: baseAddress, blockBuffer: block, offsetIntoDestination: 0, dataLength: totalLength)
            }
        }

        guard let block = blockBuffer else { return }

        var sampleBuffer: CMSampleBuffer?
        var sizeArray = [totalLength]
        CMSampleBufferCreateReady(
            allocator: kCFAllocatorDefault,
            dataBuffer: block, formatDescription: format,
            sampleCount: 1, sampleTimingEntryCount: 0, sampleTimingArray: nil,
            sampleSizeEntryCount: 1, sampleSizeArray: &sizeArray,
            sampleBufferOut: &sampleBuffer)

        guard let buffer = sampleBuffer else { return }

        var flagsOut = VTDecodeInfoFlags()
        VTDecompressionSessionDecodeFrame(session, sampleBuffer: buffer, flags: [], frameRefcon: nil, infoFlagsOut: &flagsOut)
    }

    fileprivate func frameDecoded(_ imageBuffer: CVImageBuffer) {
        onDecodedFrame?(imageBuffer)
    }
}

private func decoderCallback(decompressionOutputRefCon: UnsafeMutableRawPointer?,
                              sourceFrameRefCon: UnsafeMutableRawPointer?,
                              status: OSStatus,
                              infoFlags: VTDecodeInfoFlags,
                              imageBuffer: CVImageBuffer?,
                              presentationTimeStamp: CMTime,
                              presentationDuration: CMTime) {
    guard status == noErr, let buffer = imageBuffer, let refcon = decompressionOutputRefCon else { return }
    let decoder = Unmanaged<VideoDecoder>.fromOpaque(refcon).takeUnretainedValue()
    decoder.frameDecoded(buffer)
}

import Foundation
import AudioToolbox

public class ClientAudioPlayer {
    private var queue: AudioQueueRef?
    private let queueAccessQueue = DispatchQueue(label: "eclipticrd.audioplayer")
    private var isRunning = false
    private let format: AudioStreamBasicDescription

    public init() {
        // Configure ASBD for ScreenCaptureKit standard: 48kHz Stereo Float32 Interleaved
        var asbd = AudioStreamBasicDescription()
        asbd.mSampleRate = 48000.0
        asbd.mFormatID = kAudioFormatLinearPCM
        asbd.mFormatFlags = kAudioFormatFlagIsFloat | kAudioFormatFlagIsPacked
        asbd.mBytesPerPacket = 8 // 4 bytes (Float32) * 2 channels
        asbd.mFramesPerPacket = 1
        asbd.mBytesPerFrame = 8
        asbd.mChannelsPerFrame = 2
        asbd.mBitsPerChannel = 32
        self.format = asbd
    }

    deinit {
        stop()
    }

    public func start() {
        queueAccessQueue.sync {
            guard !isRunning else { return }

            var tempQueue: AudioQueueRef?
            var fmt = format
            // Create a low-latency playback output queue
            let status = AudioQueueNewOutput(&fmt, { _, _, _ in }, nil, nil, nil, 0, &tempQueue)

            guard status == noErr, let q = tempQueue else {
                ERDLog.error("[AudioPlayer] Failed to create AudioQueue: \(status)")
                return
            }

            self.queue = q
            AudioQueueStart(q, nil)
            self.isRunning = true
            ERDLog.info("[AudioPlayer] Started AudioQueue playback")
        }
    }

    public func stop() {
        queueAccessQueue.sync {
            guard isRunning, let q = queue else { return }
            AudioQueueStop(q, true)
            AudioQueueDispose(q, true)
            self.queue = nil
            self.isRunning = false
            ERDLog.info("[AudioPlayer] Stopped AudioQueue playback")
        }
    }

    public func play(data: Data) {
        queueAccessQueue.async { [weak self] in
            guard let self = self, self.isRunning, let q = self.queue else { return }

            var buffer: AudioQueueBufferRef?
            let status = AudioQueueAllocateBuffer(q, UInt32(data.count), &buffer)

            guard status == noErr, let buf = buffer else { return }

            // Copy audio payload into native buffer
            data.withUnsafeBytes { rawBuffer in
                if let baseAddress = rawBuffer.baseAddress {
                    memcpy(buf.pointee.mAudioData, baseAddress, data.count)
                }
            }
            buf.pointee.mAudioDataByteSize = UInt32(data.count)

            // Enqueue buffer for immediate zero-latency audio playback
            AudioQueueEnqueueBuffer(q, buf, 0, nil)
        }
    }
}

import SwiftUI
import Network

@MainActor
final class ConnectionManager: ObservableObject {
    enum State {
        case disconnected
        case connecting
        case connected
        case error(String)
    }

    enum StreamQualityPreset: String, CaseIterable, Identifiable {
        case efficient
        case balanced
        case fluid

        var id: String { rawValue }

        var title: String {
            switch self {
            case .efficient: return "Efficient"
            case .balanced: return "Balanced"
            case .fluid: return "Fluid"
            }
        }

        var detail: String {
            switch self {
            case .efficient: return "4 Mbps · 30 fps"
            case .balanced: return "8 Mbps · 60 fps"
            case .fluid: return "12 Mbps · 90 fps"
            }
        }

        var bitrate: Int {
            switch self {
            case .efficient: return 4_000_000
            case .balanced: return ERDConstants.defaultBitrate
            case .fluid: return 12_000_000
            }
        }

        var framesPerSecond: Int {
            switch self {
            case .efficient: return 30
            case .balanced: return ERDConstants.defaultFPS
            case .fluid: return 90
            }
        }
    }

    enum StreamResolutionPreset: String, CaseIterable, Identifiable {
        case native
        case retina1440
        case desktop1080
        case compact720

        var id: String { rawValue }

        var title: String {
            switch self {
            case .native: return "Native"
            case .retina1440: return "1440p"
            case .desktop1080: return "1080p"
            case .compact720: return "720p"
            }
        }

        var detail: String {
            switch self {
            case .native: return "Match host display"
            case .retina1440: return "Sharp desktop fit"
            case .desktop1080: return "Balanced clarity"
            case .compact720: return "Bandwidth saver"
            }
        }

        func dimensions(for nativeWidth: Int, nativeHeight: Int) -> (width: Int, height: Int) {
            switch self {
            case .native:
                return Self.evenDimensions(width: nativeWidth, height: nativeHeight)
            case .retina1440:
                return Self.fittedDimensions(nativeWidth: nativeWidth, nativeHeight: nativeHeight, maxWidth: 2560, maxHeight: 1440)
            case .desktop1080:
                return Self.fittedDimensions(nativeWidth: nativeWidth, nativeHeight: nativeHeight, maxWidth: 1920, maxHeight: 1080)
            case .compact720:
                return Self.fittedDimensions(nativeWidth: nativeWidth, nativeHeight: nativeHeight, maxWidth: 1280, maxHeight: 720)
            }
        }

        private static func fittedDimensions(nativeWidth: Int, nativeHeight: Int, maxWidth: Int, maxHeight: Int) -> (width: Int, height: Int) {
            guard nativeWidth > 0, nativeHeight > 0 else {
                return evenDimensions(width: maxWidth, height: maxHeight)
            }

            let widthScale = CGFloat(maxWidth) / CGFloat(nativeWidth)
            let heightScale = CGFloat(maxHeight) / CGFloat(nativeHeight)
            let scale = min(widthScale, heightScale, 1)
            let fittedWidth = Int((CGFloat(nativeWidth) * scale).rounded(.down))
            let fittedHeight = Int((CGFloat(nativeHeight) * scale).rounded(.down))
            return evenDimensions(width: fittedWidth, height: fittedHeight)
        }

        private static func evenDimensions(width: Int, height: Int) -> (width: Int, height: Int) {
            let normalizedWidth = max(2, width - (width % 2))
            let normalizedHeight = max(2, height - (height % 2))
            return (normalizedWidth, normalizedHeight)
        }
    }

    enum SessionControlStatus {
        case ready
        case pending
        case applied
        case rejected
    }

    struct SessionControlState {
        var selectedQuality: StreamQualityPreset = .balanced
        var activeQuality: StreamQualityPreset = .balanced
        var selectedResolution: StreamResolutionPreset = .native
        var activeResolution: StreamResolutionPreset = .native
        var activeConfiguration: StreamConfiguration?
        var pendingConfiguration: StreamConfiguration?
        var isRequestPending = false
        var status: SessionControlStatus = .ready
        var statusTitle = "Session controls ready"
        var statusMessage = "The live stream is using the current host profile."
        var isImmersiveModeEnabled = false
        var isFullscreen = false

        var activeSummary: String {
            let resolutionLabel = activeResolution.title
            let qualityLabel = activeQuality.title
            return "\(resolutionLabel) · \(qualityLabel)"
        }
    }

    @Published var state: State = .disconnected
    @Published var serverName: String?
    @Published var sessionControls = SessionControlState()
    @Published var showClipboardToast = false
    @Published var clipboardToastText = ""
    @Published var isAudioMuted = false {
        didSet {
            ClientCore.shared.isAudioMuted.value = isAudioMuted
        }
    }

    private var clipboardToastWorkItem: DispatchWorkItem?
    private var lastBonjourEndpoint: NWEndpoint?
    private var lastBonjourName: String?
    private var lastPIN: String?
    private var reconnectAttempts = 0
    private var isUserDisconnect = false
    private var reconnectWorkItem: DispatchWorkItem?
    private var streamConfigTimeoutWorkItem: DispatchWorkItem?
    private let maxReconnectAttempts = 3
    private let streamConfigRequestTimeout: TimeInterval = 10

    init() {
        ClientCore.shared.onSessionReady = { [weak self] in
            Task { @MainActor [weak self] in
                guard let self else { return }
                self.reconnectAttempts = 0
                self.state = .connected
                self.resetSessionControlsForConnectedSession()
            }
        }
        ClientCore.shared.onServerIdentity = { [weak self] serverName in
            Task { @MainActor [weak self] in
                self?.serverName = serverName
            }
        }
        ClientCore.shared.onDisconnected = { [weak self] in
            Task { @MainActor [weak self] in
                guard let self else { return }
                self.sessionControls.isImmersiveModeEnabled = false
                self.sessionControls.isFullscreen = false
                self.cancelStreamConfigRequestTimeout()

                if self.isUserDisconnect {
                    self.isUserDisconnect = false
                    self.state = .disconnected
                    self.serverName = nil
                    self.sessionControls = SessionControlState()
                    return
                }
                self.attemptReconnect()
            }
        }
        ClientCore.shared.onError = { [weak self] message in
            Task { @MainActor [weak self] in
                self?.state = .error(message)
            }
        }
        ClientCore.shared.onStreamConfigResponse = { [weak self] response in
            Task { @MainActor [weak self] in
                self?.handleStreamConfigResponse(response)
            }
        }
        ClientCore.shared.onStreamConfigRejected = { [weak self] rejection in
            Task { @MainActor [weak self] in
                self?.handleStreamConfigRejection(rejection)
            }
        }
        ClientCore.shared.onStreamConfigError = { [weak self] error in
            Task { @MainActor [weak self] in
                self?.handleStreamConfigError(error)
            }
        }
        ClientCore.shared.onClipboardSynced = { [weak self] text in
            Task { @MainActor [weak self] in
                self?.triggerClipboardToast(text: text)
            }
        }
    }

    func connectBonjour(endpoint: NWEndpoint, name: String) {
        cancelStreamConfigRequestTimeout()
        reconnectAttempts = 0
        isUserDisconnect = false
        state = .connecting
        serverName = name
        sessionControls = SessionControlState()
        lastBonjourEndpoint = endpoint
        lastBonjourName = name
        lastPIN = nil
        ClientCore.shared.start(endpoint: endpoint, name: name)
    }

    func connectPIN(pin: String) {
        cancelStreamConfigRequestTimeout()
        reconnectAttempts = 0
        isUserDisconnect = false
        state = .connecting
        sessionControls = SessionControlState()
        lastPIN = pin
        lastBonjourEndpoint = nil
        lastBonjourName = nil
        ClientCore.shared.startICE(pin: pin)
    }

    func disconnect() {
        reconnectWorkItem?.cancel()
        reconnectWorkItem = nil
        cancelStreamConfigRequestTimeout()
        isUserDisconnect = true
        reconnectAttempts = 0
        sessionControls.isImmersiveModeEnabled = false
        sessionControls.isFullscreen = false
        ClientCore.shared.stop()
        state = .disconnected
        serverName = nil
        sessionControls = SessionControlState()
    }

    func retry() {
        reconnectAttempts = 0
        performReconnect()
    }

    func requestStreamConfiguration(quality: StreamQualityPreset? = nil, resolution: StreamResolutionPreset? = nil) {
        if let quality {
            sessionControls.selectedQuality = quality
        }

        if let resolution {
            sessionControls.selectedResolution = resolution
        }

        guard !sessionControls.isRequestPending else { return }
        guard let config = buildRequestedConfiguration() else {
            sessionControls.status = .ready
            sessionControls.statusTitle = "Waiting for host display"
            sessionControls.statusMessage = "Stream controls become active after the session reports the host resolution."
            return
        }

        sessionControls.pendingConfiguration = config
        sessionControls.isRequestPending = true
        sessionControls.status = .pending
        sessionControls.statusTitle = "Requesting stream update"
        sessionControls.statusMessage = "Asking the host for \(sessionControls.selectedResolution.title) at \(sessionControls.selectedQuality.detail)."

        ClientCore.shared.requestStreamConfiguration(config)
        scheduleStreamConfigRequestTimeout()
    }

    func setImmersiveModeEnabled(_ enabled: Bool) {
        sessionControls.isImmersiveModeEnabled = enabled
        if !enabled {
            sessionControls.isFullscreen = false
        }
    }

    func updateFullscreenState(_ isFullscreen: Bool) {
        sessionControls.isFullscreen = isFullscreen
        if !isFullscreen {
            sessionControls.isImmersiveModeEnabled = false
        }
    }

    private func attemptReconnect() {
        guard reconnectAttempts < maxReconnectAttempts else {
            state = .error("Connection lost after \(maxReconnectAttempts) retries")
            return
        }

        guard lastBonjourEndpoint != nil || lastPIN != nil else {
            cancelStreamConfigRequestTimeout()
            state = .disconnected
            serverName = nil
            sessionControls = SessionControlState()
            return
        }

        let delay = pow(2.0, Double(reconnectAttempts))
        reconnectAttempts += 1
        state = .connecting

        let work = DispatchWorkItem { [weak self] in
            self?.performReconnect()
        }
        reconnectWorkItem = work
        DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: work)
    }

    private func performReconnect() {
        if let endpoint = lastBonjourEndpoint, let name = lastBonjourName {
            state = .connecting
            serverName = name
            cancelStreamConfigRequestTimeout()
            ClientCore.shared.start(endpoint: endpoint, name: name)
        } else if let pin = lastPIN {
            state = .connecting
            cancelStreamConfigRequestTimeout()
            ClientCore.shared.startICE(pin: pin)
        } else {
            state = .disconnected
        }
    }

    private func resetSessionControlsForConnectedSession() {
        let nativeWidth = ClientCore.shared.serverScreenWidth
        let nativeHeight = ClientCore.shared.serverScreenHeight
        let defaultConfiguration = StreamConfiguration(
            width: UInt32(max(2, nativeWidth)),
            height: UInt32(max(2, nativeHeight)),
            bitrate: UInt32(ERDConstants.defaultBitrate),
            framesPerSecond: UInt16(ERDConstants.defaultFPS)
        )

        sessionControls = SessionControlState(
            selectedQuality: .balanced,
            activeQuality: .balanced,
            selectedResolution: .native,
            activeResolution: .native,
            activeConfiguration: defaultConfiguration,
            pendingConfiguration: nil,
            isRequestPending: false,
            status: .ready,
            statusTitle: "Native stream live",
            statusMessage: "Use the floating controls to tune quality, resolution, or enter immersive mode.",
            isImmersiveModeEnabled: false,
            isFullscreen: false
        )
        cancelStreamConfigRequestTimeout()
    }

    private func buildRequestedConfiguration() -> StreamConfiguration? {
        let nativeWidth = ClientCore.shared.serverScreenWidth
        let nativeHeight = ClientCore.shared.serverScreenHeight

        guard nativeWidth > 0, nativeHeight > 0 else {
            return nil
        }

        let dimensions = sessionControls.selectedResolution.dimensions(for: nativeWidth, nativeHeight: nativeHeight)
        return StreamConfiguration(
            width: UInt32(dimensions.width),
            height: UInt32(dimensions.height),
            bitrate: UInt32(sessionControls.selectedQuality.bitrate),
            framesPerSecond: UInt16(sessionControls.selectedQuality.framesPerSecond)
        )
    }

    private func handleStreamConfigResponse(_ response: StreamConfigurationResponsePayload) {
        let activeConfiguration = response.activeConfiguration
        let nativeWidth = ClientCore.shared.serverScreenWidth
        let nativeHeight = ClientCore.shared.serverScreenHeight
        let matchedQuality = nearestQualityPreset(for: activeConfiguration)
        let matchedResolution = nearestResolutionPreset(for: activeConfiguration, nativeWidth: nativeWidth, nativeHeight: nativeHeight)

        sessionControls.activeConfiguration = activeConfiguration
        sessionControls.pendingConfiguration = nil
        sessionControls.isRequestPending = false
        cancelStreamConfigRequestTimeout()
        sessionControls.activeQuality = matchedQuality
        sessionControls.selectedQuality = matchedQuality
        sessionControls.activeResolution = matchedResolution
        sessionControls.selectedResolution = matchedResolution
        sessionControls.status = .applied
        sessionControls.statusTitle = "Stream profile applied"
        sessionControls.statusMessage = "Live at \(Int(activeConfiguration.width))×\(Int(activeConfiguration.height)) · \(Int(activeConfiguration.framesPerSecond)) fps · \(formatBitrate(Int(activeConfiguration.bitrate)))."
    }

    private func handleStreamConfigRejection(_ rejection: StreamConfigurationRejectPayload) {
        cancelStreamConfigRequestTimeout()
        sessionControls.pendingConfiguration = nil
        sessionControls.isRequestPending = false
        sessionControls.selectedQuality = sessionControls.activeQuality
        sessionControls.selectedResolution = sessionControls.activeResolution
        sessionControls.status = .rejected
        sessionControls.statusTitle = "Host kept current stream"
        sessionControls.statusMessage = rejection.message.isEmpty ? "The host rejected the requested stream profile." : rejection.message
    }

    private func handleStreamConfigError(_ error: StreamConfigurationErrorPayload) {
        cancelStreamConfigRequestTimeout()
        sessionControls.pendingConfiguration = nil
        sessionControls.isRequestPending = false
        sessionControls.selectedQuality = sessionControls.activeQuality
        sessionControls.selectedResolution = sessionControls.activeResolution
        sessionControls.status = .rejected
        sessionControls.statusTitle = "Stream update error"
        sessionControls.statusMessage = error.message.isEmpty ? "The host returned an error while applying the requested stream profile." : error.message
    }

    private func nearestQualityPreset(for configuration: StreamConfiguration) -> StreamQualityPreset {
        StreamQualityPreset.allCases.min { lhs, rhs in
            qualityDistance(from: lhs, to: configuration) < qualityDistance(from: rhs, to: configuration)
        } ?? .balanced
    }

    private func nearestResolutionPreset(for configuration: StreamConfiguration, nativeWidth: Int, nativeHeight: Int) -> StreamResolutionPreset {
        StreamResolutionPreset.allCases.min { lhs, rhs in
            resolutionDistance(from: lhs, to: configuration, nativeWidth: nativeWidth, nativeHeight: nativeHeight) < resolutionDistance(from: rhs, to: configuration, nativeWidth: nativeWidth, nativeHeight: nativeHeight)
        } ?? .native
    }

    private func qualityDistance(from preset: StreamQualityPreset, to configuration: StreamConfiguration) -> Int {
        abs(preset.bitrate - Int(configuration.bitrate)) + (abs(preset.framesPerSecond - Int(configuration.framesPerSecond)) * 100_000)
    }

    private func resolutionDistance(from preset: StreamResolutionPreset, to configuration: StreamConfiguration, nativeWidth: Int, nativeHeight: Int) -> Int {
        let dimensions = preset.dimensions(for: nativeWidth, nativeHeight: nativeHeight)
        return abs(dimensions.width - Int(configuration.width)) + abs(dimensions.height - Int(configuration.height))
    }

    private func formatBitrate(_ bitrate: Int) -> String {
        let mbps = Double(bitrate) / 1_000_000.0
        return String(format: "%.1f Mbps", mbps)
    }

    private func scheduleStreamConfigRequestTimeout() {
        streamConfigTimeoutWorkItem?.cancel()

        let workItem = DispatchWorkItem { [weak self] in
            guard let self, self.sessionControls.isRequestPending else { return }
            self.sessionControls.pendingConfiguration = nil
            self.sessionControls.isRequestPending = false
            self.sessionControls.selectedQuality = self.sessionControls.activeQuality
            self.sessionControls.selectedResolution = self.sessionControls.activeResolution
            self.sessionControls.status = .rejected
            self.sessionControls.statusTitle = "Stream update timed out"
            self.sessionControls.statusMessage = "The host did not respond in time. Please try again."
        }

        streamConfigTimeoutWorkItem = workItem
        DispatchQueue.main.asyncAfter(deadline: .now() + streamConfigRequestTimeout, execute: workItem)
    }

    private func cancelStreamConfigRequestTimeout() {
        streamConfigTimeoutWorkItem?.cancel()
        streamConfigTimeoutWorkItem = nil
    }

    private func triggerClipboardToast(text: String) {
        clipboardToastWorkItem?.cancel()

        let preview = text.count > 15 ? String(text.prefix(12)) + "..." : text
        clipboardToastText = "Clipboard Synced: \"\(preview)\""
        showClipboardToast = true

        let work = DispatchWorkItem { [weak self] in
            withAnimation(.easeInOut(duration: 0.22)) {
                self?.showClipboardToast = false
            }
        }
        clipboardToastWorkItem = work
        DispatchQueue.main.asyncAfter(deadline: .now() + 2.5, execute: work)
    }
}

import SwiftUI

class HomeBonjourBrowserManager: ObservableObject {
    @Published var hosts: [BonjourBrowser.DiscoveredHost] = []
    private let browser = BonjourBrowser()

    init() {
        browser.onHostsChanged = { [weak self] hosts in
            DispatchQueue.main.async { self?.hosts = hosts }
        }
    }

    func startBrowsing() { browser.startBrowsing() }
    func stopBrowsing() { browser.stopBrowsing() }
}

struct HomeView: View {
    @EnvironmentObject var connectionManager: ConnectionManager
    @State private var isServerRunning = ServerCore.shared.isRunning
    @State private var serverPIN = String(format: "%06d", Int.random(in: 0..<1_000_000))
    @State private var manualPIN = ""

    // Sidebar Navigation Tab enum
    enum Tab {
        case computers
        case settings
    }
    @State private var activeTab: Tab = .computers

    @StateObject private var browserManager = HomeBonjourBrowserManager()
    @State private var showDiscoveryEmptyState = false
    @State private var discoveryStateTask: Task<Void, Never>?

    @AppStorage("preferredCodec") private var preferredCodec = "HEVC"
    @AppStorage("preferredFPS") private var preferredFPS = 60
    @AppStorage("hostAudioEnabled") private var hostAudioEnabled = true

    private var isManualPINValid: Bool {
        manualPIN.trimmingCharacters(in: .whitespacesAndNewlines).count == 6
    }

    var body: some View {
        Group {
            switch connectionManager.state {
            case .connected:
                RemoteDesktopView()
            case .connecting:
                connectingContent
            case .error(let message):
                errorContent(message: message)
            case .disconnected:
                navigationDashboardLayout
            }
        }
        .preferredColorScheme(.dark)
        .onAppear {
            isServerRunning = ServerCore.shared.isRunning
            ServerCore.shared.onRunningChanged = { running in
                DispatchQueue.main.async {
                    isServerRunning = running
                }
            }
            beginDiscoveryPresentation()
        }
        .onDisappear {
            ServerCore.shared.onRunningChanged = nil
            discoveryStateTask?.cancel()
            discoveryStateTask = nil
            browserManager.stopBrowsing()
        }
    }

    // Modern Sidebar + Content Area Navigation Layout
    private var navigationDashboardLayout: some View {
        HStack(spacing: 0) {
            sidebarPanel

            Divider()
                .background(ERDTheme.panelBorder)

            contentPane
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
        .frame(minWidth: 880, minHeight: 520)
        .background(ERDAppBackground())
    }

    // Beautiful Parsec-style Sidebar
